    let buffer = '';

    const onData = (e) => {
        if (requestSeq.current[id] !== requestId) return;
        const token = e.detail && e.detail.message ? (e.detail.message.content || '') : '';
        buffer += token;
        updatePane(id, (p) => ({
            chatLog: p.chatLog.map((m) => m.id === liveId ? { ...m, content: buffer } : m),
        }));
    };

    function cleanup() {
        window.removeEventListener('llm-stream-data', onData);
        window.removeEventListener('llm-stream-complete', onComplete);
        window.removeEventListener('llm-stream-error', onError);
    }

    function finish(finalContent) {
        cleanup();
        if (requestSeq.current[id] !== requestId) return;
        updatePane(id, (p) => ({
            isThinking: false,
            chatLog: p.chatLog.map((m) => m.id === liveId
                ? { ...m, content: finalContent !== undefined ? finalContent : buffer, _streaming: false }
                : m),
        }));
        resolve();
    }

    function onComplete() {
        finish();
    }

    function onError(e) {
        const msg = e && e.detail ? String(e.detail) : 'Stream error';
        finish(buffer || `Error: ${msg}`);
    }

    window.addEventListener('llm-stream-data', onData);
    window.addEventListener('llm-stream-complete', onComplete);
    window.addEventListener('llm-stream-error', onError);

