import { useEffect, useRef } from 'react';

const FOCUSABLE_SELECTOR = [
    'a[href]:not([disabled])',
    'button:not([disabled])',
    'textarea:not([disabled])',
    'input:not([type="hidden"]):not([disabled])',
    'select:not([disabled])',
    '[tabindex]:not([tabindex="-1"]):not([disabled])',
].join(',');

function isVisible(el) {
    if (!el || typeof el.getClientRects !== 'function') return false;
    const rects = el.getClientRects();
    if (!rects || !rects.length) return false;
    if (el.getAttribute('aria-hidden') === 'true') return false;
    const style = typeof window !== 'undefined' ? window.getComputedStyle(el) : null;
    if (style && (style.visibility === 'hidden' || style.display === 'none')) return false;
    return true;
}

export function getFocusableElements(root) {
    if (!root || typeof root.querySelectorAll !== 'function') return [];
    return Array.from(root.querySelectorAll(FOCUSABLE_SELECTOR)).filter(isVisible);
}

/**
 * Trap Tab focus inside `rootRef` while `active` is true. Optionally restores focus on teardown.
 * @param {boolean} active
 * @param {React.RefObject<HTMLElement|null>} rootRef
 * @param {{ restoreFocus?: boolean, initialSelector?: string|null }} [options]
 */
export function useFocusTrap(active, rootRef, options = {}) {
    const { restoreFocus = true, initialSelector = null } = options;
    const lastFocusedRef = useRef(null);

    useEffect(() => {
        if (!active) return undefined;
        const root = rootRef?.current;
        if (!root) return undefined;

        if (restoreFocus && document.activeElement && typeof document.activeElement.focus === 'function') {
            lastFocusedRef.current = document.activeElement;
        }

        const runInitialFocus = () => {
            if (initialSelector) {
                const el = root.querySelector(initialSelector);
                if (el && typeof el.focus === 'function') {
                    el.focus();
                    return;
                }
            }
            const nodes = getFocusableElements(root);
            if (nodes.length && typeof nodes[0].focus === 'function') {
                nodes[0].focus();
            }
        };

        runInitialFocus();
        const raf = typeof requestAnimationFrame === 'function' ? requestAnimationFrame(runInitialFocus) : 0;

        const onKeyDown = (event) => {
            if (event.key !== 'Tab') return;
            const nodes = getFocusableElements(root);
            if (!nodes.length) return;
            const first = nodes[0];
            const last = nodes[nodes.length - 1];
            const activeEl = document.activeElement;
            if (event.shiftKey) {
                if (activeEl === first || !root.contains(activeEl)) {
                    event.preventDefault();
                    last.focus();
                }
            } else if (activeEl === last || !root.contains(activeEl)) {
                event.preventDefault();
                first.focus();
            }
        };

        document.addEventListener('keydown', onKeyDown, true);
        return () => {
            if (typeof cancelAnimationFrame === 'function') cancelAnimationFrame(raf);
            document.removeEventListener('keydown', onKeyDown, true);
            const prev = lastFocusedRef.current;
            if (restoreFocus && prev && typeof prev.focus === 'function') {
                try {
                    prev.focus();
                } catch {
                    /* ignore */
                }
            }
            lastFocusedRef.current = null;
        };
    }, [active, rootRef, restoreFocus, initialSelector]);
}

/**
 * Arrow / Home / End keyboard navigation between [data-testid="chat-message"] roots.
 * @param {KeyboardEvent} e
 * @param {HTMLElement | null} lane
 * @returns {boolean} true if the event was handled (caller should not run other handlers)
 */
export function handleChatMessageListArrowKeyDown(e, lane) {
    if (!lane) return false;
    const { key } = e;
    if (!['ArrowUp', 'ArrowDown', 'Home', 'End'].includes(key)) return false;
    const { target } = e;
    if (
        target
        && (target.tagName === 'INPUT'
            || target.tagName === 'TEXTAREA'
            || target.tagName === 'SELECT'
            || target.isContentEditable)
    ) {
        return false;
    }
    if (
        target !== lane
        && typeof target.closest === 'function'
        && !target.closest('[data-testid="chat-message"]')
    ) {
        return false;
    }
    const messages = Array.from(lane.querySelectorAll('[data-testid="chat-message"]'));
    if (!messages.length) return false;
    e.preventDefault();
    let idx = messages.indexOf(document.activeElement);
    if (idx < 0 && document.activeElement === lane) idx = -1;

    if (key === 'Home') {
        messages[0].focus();
        return true;
    }
    if (key === 'End') {
        messages[messages.length - 1].focus();
        return true;
    }
    if (key === 'ArrowDown') {
        if (idx < 0) messages[0].focus();
        else if (idx < messages.length - 1) messages[idx + 1].focus();
        return true;
    }
    if (key === 'ArrowUp') {
        if (idx < 0) messages[messages.length - 1].focus();
        else if (idx > 0) messages[idx - 1].focus();
        else lane.focus();
        return true;
    }
    return false;
}

