import { useEffect } from 'react';
import { useFocusTrap } from './useFocusTrap.js';

/**
 * Modal / overlay accessibility: trap Tab focus inside `panelRef` while `open`,
 * restore focus on close, and close on Escape (capture phase).
 *
 * @param {boolean} open
 * @param {import('react').RefObject<HTMLElement|null>} panelRef
 * @param {() => void} [onClose]
 * @param {{ initialSelector?: string|null }} [options]
 *   initialSelector — first focus target; defaults to `[data-accessible-overlay-close]`
 */
export function useModalAccessibility(open, panelRef, onClose, options = {}) {
    const { initialSelector = '[data-accessible-overlay-close]' } = options;

    useFocusTrap(open, panelRef, { initialSelector });

    useEffect(() => {
        if (!open) return undefined;
        const onKey = (e) => {
            if (e.key === 'Escape' && typeof onClose === 'function') onClose();
        };
        window.addEventListener('keydown', onKey, true);
        return () => window.removeEventListener('keydown', onKey, true);
    }, [open, onClose]);
}

/**
 * One-shot codemod: add useModalAccessibility + dialog semantics to cyan-header console shells.
 * Run from repo: node src/renderer/scripts/patch-console-modal-a11y.mjs
 * (cwd must be src/renderer)
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const COMPONENTS = path.join(__dirname, '../src/components');

const PATCHES = [
    ['CommercialPackageConsole.jsx', 'commercial-package-console-title', '[data-testid="commercial-close-btn"]'],
    ['BuyerEvaluationCenter.jsx', 'buyer-evaluation-center-title', '[data-testid="buyer-close-btn"]'],
    ['OfflineUpdateConsole.jsx', 'offline-update-console-title', '[data-testid="offline-update-close-btn"]'],
    ['DeploymentProgramCenter.jsx', 'deployment-program-center-title', '[data-testid="deployment-close-btn"]'],
    ['ApplianceConsole.jsx', 'appliance-console-title', '[data-testid="appliance-close-btn"]'],
    ['PolicyRolloutConsole.jsx', 'policy-rollout-console-title', '[data-testid="policy-rollout-close-btn"]'],
    ['PilotExpansionConsole.jsx', 'pilot-expansion-console-title', '[data-testid="pilot-expansion-close-btn"]'],
    ['PilotConversionConsole.jsx', 'pilot-conversion-console-title', '[data-testid="pilot-close-btn"]'],
    ['PartnerRolloutConsole.jsx', 'partner-rollout-console-title', '[data-testid="partner-rollout-close-btn"]'],
    ['ManagedServicesConsole.jsx', 'managed-services-console-title', '[data-testid="managed-services-close-btn"]'],
    ['GlobalPlanningConsole.jsx', 'global-planning-console-title', '[data-testid="global-planning-close-btn"]'],
    ['FieldFeedbackConsole.jsx', 'field-feedback-console-title', '[data-testid="field-feedback-close-btn"]'],
    ['EcosystemPortfolioConsole.jsx', 'ecosystem-portfolio-console-title', '[data-testid="ecosystem-portfolio-close-btn"]'],
    ['DemoToPilotConsole.jsx', 'demo-to-pilot-console-title', '[data-testid="demo-to-pilot-close-btn"]'],
    ['BoardOperatingPackConsole.jsx', 'board-operating-pack-console-title', '[data-testid="board-operating-close-btn"]'],
    ['BuyerOpsConsole.jsx', 'buyer-ops-console-title', '[data-testid="buyer-ops-close-btn"]'],
    ['RevenueOpsConsole.jsx', 'revenue-ops-console-title', '[data-testid="revenue-ops-close-btn"]'],
    ['RenewalRiskConsole.jsx', 'renewal-risk-console-title', '[data-testid="renewal-risk-close-btn"]'],
    ['ServiceLineConsole.jsx', 'service-line-console-title', '[data-testid="service-line-close-btn"]'],
    ['StrategicAccountConsole.jsx', 'strategic-account-console-title', '[data-testid="strategic-account-close-btn"]'],
    ['SupportOpsConsole.jsx', 'support-ops-console-title', '[data-testid="support-close-btn"]'],
    ['ShiftConsole.jsx', 'shift-console-title', '[data-testid="shift-console-close-btn"]'],
    ['TrustFabricConsole.jsx', 'trust-fabric-console-title', '[data-testid="trust-fabric-close-btn"]'],
    ['InstitutionalCommandConsole.jsx', 'institutional-command-console-title', '[data-testid="institutional-close-btn"]'],
    ['EcosystemCommandCenter.jsx', 'ecosystem-command-center-title', '[data-testid="ecosystem-command-close-btn"]'],
    ['DemoFlowConsole.jsx', 'demo-flow-console-title', '[data-testid="demo-flow-close-btn"]'],
];

const HOOK_BLOCK = (sel) => `    const panelRef = React.useRef(null);
    useModalAccessibility(open, panelRef, onClose, { initialSelector: '${sel}' });

`;

const TITLE_RE = /<div className="text-\[10px\] uppercase tracking-\[0\.16em\] text-cyan-300 font-bold">([^<]+)<\/div>/;

function patchContent(raw, titleId, sel) {
    if (raw.includes('useModalAccessibility')) return null;
    let c = raw;
    if (c.includes('import React from "react";')) {
        c = c.replace(
            'import React from "react";',
            'import React from "react";\nimport { useModalAccessibility } from "../hooks/useModalAccessibility.js";',
        );
    } else if (c.includes("import React from 'react';")) {
        c = c.replace(
            "import React from 'react';",
            "import React from 'react';\nimport { useModalAccessibility } from '../hooks/useModalAccessibility.js';",
        );
    } else {
        return null;
    }

    if (!c.includes('if (!open) return null;')) return null;

    c = c.replace('if (!open) return null;', () => `${HOOK_BLOCK(sel)}    if (!open) return null;`);

    c = c.replace(
        /<div className="fixed inset-0 z-\[[^\]]+\] bg-black\/60" onClick={onClose} \/>/,
        (m) => m.replace(/\s*\/>$/, ' aria-hidden="true" />'),
    );

    c = c.replace(
        /<section data-testid="/g,
        `<section ref={panelRef} role="dialog" aria-modal="true" aria-labelledby="${titleId}" data-testid="`,
    );

    if (TITLE_RE.test(c)) {
        c = c.replace(
            TITLE_RE,
            `<h2 id="${titleId}" className="text-[10px] uppercase tracking-[0.16em] text-cyan-300 font-bold">$1</h2>`,
        );
    }

    return c;
}

let n = 0;
for (const [file, titleId, sel] of PATCHES) {
    const fp = path.join(COMPONENTS, file);
    if (!fs.existsSync(fp)) {
        console.warn('skip missing', file);
        continue;
    }
    const raw = fs.readFileSync(fp, 'utf8');
    const next = patchContent(raw, titleId, sel);
    if (next == null || next === raw) {
        console.warn('skip unchanged', file);
        continue;
    }
    fs.writeFileSync(fp, next);
    console.log('patched', file);
    n++;
}
console.log('done', n);

