#!/usr/bin/env node
/**
 * CI guard: commercial plans and runtime tiers must agree on capability sets per plan id.
 * Also root vs renderer plans.json must match (prevents drift in checkout UI vs license engine).
 */
const assert = require("assert");
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");

function readJson(rel) {
  const raw = fs.readFileSync(path.join(root, rel), "utf8");
  return JSON.parse(raw);
}

function sortedUniqueCaps(list) {
  return Array.from(
    new Set(
      (Array.isArray(list) ? list : [])
        .map((entry) => String(entry || "").trim())
        .filter(Boolean)
    )
  ).sort();
}

function capsForPlan(plansDoc, planId) {
  const plans = Array.isArray(plansDoc.plans) ? plansDoc.plans : [];
  const plan = plans.find((p) => String(p && p.id ? p.id : "").toLowerCase() === planId);
  assert.ok(plan, `plan ${planId} missing in ${plansDoc._path || "plans"}`);
  return sortedUniqueCaps(plan.capabilities);
}

function capsForTier(tiersDoc, tierId) {
  const tiers = Array.isArray(tiersDoc.tiers) ? tiersDoc.tiers : [];
  const tier = tiers.find((t) => String(t && t.id ? t.id : "").toLowerCase() === tierId);
  assert.ok(tier, `tier ${tierId} missing in tiers.json`);
  return sortedUniqueCaps(tier.capabilities);
}

try {
  const tiers = readJson("config/tiers.json");
  const plansRoot = readJson("config/plans.json");
  const plansRenderer = readJson("src/renderer/src/config/plans.json");

  for (const id of ["free", "pro", "enterprise"]) {
    const fromPlans = capsForPlan(plansRoot, id);
    const fromTiers = capsForTier(tiers, id);
    assert.deepStrictEqual(
      fromPlans,
      fromTiers,
      `config/plans.json and config/tiers.json must list the same capabilities for "${id}"`
    );
  }

  for (const id of ["free", "pro", "enterprise"]) {
    assert.deepStrictEqual(
      capsForPlan(plansRoot, id),
      capsForPlan(plansRenderer, id),
      `src/renderer/src/config/plans.json must match config/plans.json for "${id}"`
    );
  }

  assert.strictEqual(plansRoot.version, plansRenderer.version, "plans.json version must match");
  console.log("✓ plans / tiers / renderer capability parity OK");
} catch (err) {
  console.error("\nplans-tiers-capability-parity.test.js failed:");
  console.error(err && err.message ? err.message : err);
  process.exit(1);
}

#!/usr/bin/env node
/**
 * Enterprise ecosystem modules must declare capability (cap-gated access).
 * Every capability id referenced in ecosystem.ts must exist on at least one tier allow-list.
 */
const assert = require("assert");
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const ecoPath = path.join(root, "src", "renderer", "src", "routes", "ecosystem.ts");

function loadAllTierCapabilities() {
  const tiers = JSON.parse(fs.readFileSync(path.join(root, "config", "tiers.json"), "utf8"));
  const union = new Set();
  for (const tier of tiers.tiers || []) {
    for (const c of tier.capabilities || []) {
      union.add(String(c || "").trim());
    }
  }
  return union;
}

try {
  const text = fs.readFileSync(ecoPath, "utf8");
  const chunks = text.split(/\n    \{\n        id: '/).slice(1);

  for (const chunk of chunks) {
    if (!chunk.includes("minTier: 'enterprise'")) continue;
    assert.ok(
      /\bcapability:\s*'[a-z0-9_]+'/.test(chunk),
      `Enterprise module must declare capability:\n…${chunk.slice(0, 120)}…`
    );
  }

  const capIds = new Set();
  const re = /\bcapability:\s*'([a-z0-9_]+)'/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    capIds.add(m[1]);
  }

  const allowed = loadAllTierCapabilities();
  for (const id of capIds) {
