#!/usr/bin/env node
/**
 * Every ecosystem module must declare a capability that exists on some tier allow-list.
 */
const assert = require("assert");
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const ecoPath = path.join(root, "src", "renderer", "src", "routes", "ecosystem.ts");

function loadAllTierCapabilities() {
  const tiers = JSON.parse(fs.readFileSync(path.join(root, "config", "tiers.json"), "utf8"));
  const union = new Set();
  for (const tier of tiers.tiers || []) {
    for (const c of tier.capabilities || []) {
      union.add(String(c || "").trim());
    }
  }
  return union;
}

try {
  const text = fs.readFileSync(ecoPath, "utf8");
  const start = text.indexOf("export const ECOSYSTEM_MODULES");
  assert.ok(start >= 0, "ECOSYSTEM_MODULES export not found");
  const sub = text.slice(start);
  const parts = sub.split(/\n        id: '/).slice(1);

  for (const part of parts) {
    const idMatch = part.match(/^([^']+)/);
    assert.ok(idMatch, "module id parse");
    const id = idMatch[1];
    assert.ok(
      /\bcapability:\s*'[a-z0-9_]+'/.test(part),
      `Ecosystem module "${id}" must declare capability: '…'`,
    );
  }

  const capIds = new Set();
  const re = /\bcapability:\s*'([a-z0-9_]+)'/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    capIds.add(m[1]);
  }

  const allowed = loadAllTierCapabilities();
  for (const id of capIds) {
    assert.ok(
      allowed.has(id),
      `ecosystem.ts references unknown capability "${id}" (not in any config/tiers.json tier)`,
    );
  }

  console.log("✓ ecosystem module capability coverage + tier vocabulary OK");
} catch (err) {
  console.error("\necosystem-capability-gates.test.js failed:");
  console.error(err && err.message ? err.message : err);
  process.exit(1);
}

