#!/usr/bin/env node
/**
 * Tier contract: each paid tier must be a strict superset of the previous tier's capabilities
 * (so license upgrades never drop rights unexpectedly and monotone checks stay meaningful).
 */
const assert = require("assert");
const fs = require("fs");
const path = require("path");

function loadTiers() {
  const p = path.join(__dirname, "..", "config", "tiers.json");
  return JSON.parse(fs.readFileSync(p, "utf8"));
}

function capSet(tier) {
  return new Set(
    (Array.isArray(tier && tier.capabilities) ? tier.capabilities : [])
      .map((c) => String(c || "").trim())
      .filter(Boolean)
  );
}

function isSubset(a, b) {
  for (const x of a) {
    if (!b.has(x)) return false;
  }
  return true;
}

try {
  const doc = loadTiers();
  const tiers = doc.tiers || [];
  const free = tiers.find((t) => t.id === "free");
  const pro = tiers.find((t) => t.id === "pro");
  const ent = tiers.find((t) => t.id === "enterprise");
  assert.ok(free && pro && ent, "free, pro, enterprise tiers required");

  const Sf = capSet(free);
  const Sp = capSet(pro);
  const Se = capSet(ent);

  assert.ok(isSubset(Sf, Sp), "pro tier must include every free-tier capability");
  assert.ok(isSubset(Sp, Se), "enterprise tier must include every pro-tier capability");
  assert.ok(Sp.size > Sf.size, "pro should strictly extend free (new capabilities)");
  assert.ok(Se.size > Sp.size, "enterprise should strictly extend pro (new capabilities)");

  console.log("✓ tiers.json monotone inclusion (free ⊂ pro ⊂ enterprise)");
} catch (err) {
  console.error("\ntiers-monotone-inclusion.test.js failed:");
  console.error(err && err.message ? err.message : err);
  process.exit(1);
}

