"use strict";

const { hasCapability } = require("./capabilities");

/**
 * Standard renderer/main IPC denial shape for missing commercial/runtime caps.
 * @param {string} required capability id from config/tiers.json
 * @returns {{ ok: false, reason: string, required: string }}
 */
function tierCapabilityDenied(required) {
  const id = String(required || "").trim();
  return {
    ok: false,
    reason: "tier_capability_required",
    required: id || "unknown"
  };
}

/**
 * @param {{ capabilities?: string[] }|null|undefined} capabilitiesPayload
 * @param {string} capabilityId
 * @returns {null | ReturnType<typeof tierCapabilityDenied>}
 */
function assertCapability(capabilitiesPayload, capabilityId) {
  const id = String(capabilityId || "").trim();
  if (!id) return tierCapabilityDenied("(missing)");
  if (!hasCapability(capabilitiesPayload, id)) {
    return tierCapabilityDenied(id);
  }
  return null;
}

/**
 * @param {{ capabilities?: string[] }|null|undefined} capabilitiesPayload
 * @param {string} capabilityId
 * @throws {Error & { code: string, required: string }}
 */
function throwUnlessCapability(capabilitiesPayload, capabilityId) {
  const denied = assertCapability(capabilitiesPayload, capabilityId);
  if (denied) {
    const err = new Error("tier_capability_required");
    err.code = "TIER_CAPABILITY_REQUIRED";
    err.required = denied.required;
    throw err;
  }
}

module.exports = {
  tierCapabilityDenied,
  assertCapability,
  throwUnlessCapability
};

