#!/usr/bin/env node
const assert = require("assert");
const {
  assertCapability,
  throwUnlessCapability,
  tierCapabilityDenied
} = require("../src/core/tierCapabilityResponse");

function testDeniedShape() {
  const d = tierCapabilityDenied("foo_bar");
  assert.strictEqual(d.ok, false);
  assert.strictEqual(d.reason, "tier_capability_required");
  assert.strictEqual(d.required, "foo_bar");
}

function testAssertCapability() {
  const caps = { capabilities: ["proof_view", "session_write"], tierId: "pro" };
  assert.strictEqual(assertCapability(caps, "proof_view"), null);
  assert.ok(assertCapability(caps, "sso_saml"));
  assert.strictEqual(assertCapability(caps, "sso_saml").required, "sso_saml");
}

function testThrowUnless() {
  const caps = { capabilities: ["proof_view"], tierId: "free" };
  throwUnlessCapability(caps, "proof_view");
  let caught = null;
  try {
    throwUnlessCapability(caps, "session_write");
  } catch (e) {
    caught = e;
  }
  assert.ok(caught);
  assert.strictEqual(caught.code, "TIER_CAPABILITY_REQUIRED");
  assert.strictEqual(caught.required, "session_write");
}

try {
  testDeniedShape();
  testAssertCapability();
  testThrowUnless();
  console.log("✓ tierCapabilityResponse contract OK");
} catch (err) {
  console.error("\ntier-capability-response.test.js failed:");
  console.error(err && err.message ? err.message : err);
  process.exit(1);
}

