#!/usr/bin/env node
/**
 * Recompute SHA-256 for every file path listed in governance/source_manifest.json.
 * Usage: node scripts/update-source-manifest-hashes.js
 */
"use strict";

const crypto = require("crypto");
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const manifestPath = path.join(root, "governance", "source_manifest.json");

function sha256File(absPath) {
  const buf = fs.readFileSync(absPath);
  return crypto.createHash("sha256").update(buf).digest("hex");
}

function main() {
  const raw = fs.readFileSync(manifestPath, "utf8");
  const doc = JSON.parse(raw);
  const files = doc.files && typeof doc.files === "object" ? doc.files : null;
  if (!files) {
    console.error("source_manifest.json missing top-level files object");
    process.exit(1);
  }
  doc.generatedAt = new Date().toISOString();
  let updated = 0;
  let missing = 0;
  for (const rel of Object.keys(files).sort()) {
    const abs = path.join(root, rel.split("/").join(path.sep));
    if (!fs.existsSync(abs)) {
      missing += 1;
      continue;
    }
    const next = sha256File(abs);
    if (files[rel] !== next) updated += 1;
    files[rel] = next;
  }
  fs.writeFileSync(manifestPath, `${JSON.stringify(doc, null, 2)}\n`, "utf8");
  console.log(`Updated governance/source_manifest.json (${updated} hashes changed, ${missing} paths missing on disk).`);
}

main();

