#!/usr/bin/env node
/**
 * Parse src/main.js for ipcMain.handle channels and detect tier/capability gates
 * (assertCapability / throwUnlessCapability) in each handler body.
 *
 * Usage:
 *   node scripts/generate-ipc-inventory.js           # write docs + governance
 *   node scripts/generate-ipc-inventory.js --check # exit 1 if outputs would change
 */
"use strict";

const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const mainPath = path.join(root, "src", "main.js");
const mdPath = path.join(root, "docs", "IPC_INVENTORY.md");
const jsonPath = path.join(root, "governance", "ipc_inventory.json");

const TIER_GATE_RE = /\b(assertCapability|throwUnlessCapability)\s*\(/;

function extractHandlers(source) {
  const re = /ipcMain\.handle\(\s*"([^"]+)"/g;
  const matches = [];
  let m;
  while ((m = re.exec(source)) !== null) {
    matches.push({ channel: m[1], index: m.index, matchLen: m[0].length });
  }
  const entries = [];
  for (let i = 0; i < matches.length; i += 1) {
    const start = matches[i].index + matches[i].matchLen;
    const end = i + 1 < matches.length ? matches[i + 1].index : source.length;
    const body = source.slice(start, end);
    const tierGated = TIER_GATE_RE.test(body);
    const line = source.slice(0, matches[i].index).split(/\r?\n/).length;
    entries.push({
      channel: matches[i].channel,
      line,
      tierGated,
    });
  }
  return entries;
}

function buildMarkdown(entries, generatedAt) {
  const gated = entries.filter((e) => e.tierGated).length;
  const lines = [
    "# IPC channel inventory",
    "",
    `Generated: **${generatedAt}** (from \`src/main.js\`).`,
    "",
    "Preload allow-list parity is enforced by \`tear/ipc-surface-test.js\`.",
    "This table shows which handlers reference **tier/capability gates** (\`assertCapability\` / \`throwUnlessCapability\`) anywhere in the handler body — not a full security proof.",
    "",
    "| Channel | Line (approx) | Tier gate present |",
    "|---------|---------------|-------------------|",
  ];
  for (const e of entries.sort((a, b) => a.channel.localeCompare(b.channel))) {
    lines.push(`| \`${e.channel}\` | ${e.line} | ${e.tierGated ? "yes" : "—"} |`);
  }
  lines.push("");
  lines.push(`**Summary:** ${entries.length} channels; **${gated}** with an explicit tier gate pattern in handler source.`);
  lines.push("");
  return `${lines.join("\n")}\n`;
}

function main() {
  const check = process.argv.includes("--check");
  const source = fs.readFileSync(mainPath, "utf8");
  const generatedAt = new Date().toISOString();
  const entries = extractHandlers(source);
  const md = buildMarkdown(entries, generatedAt);
  const json = JSON.stringify(
    {
      version: 1,
      generatedAt,
      source: "src/main.js",
      summary: {
        channels: entries.length,
        tierGatedHandlers: entries.filter((e) => e.tierGated).length,
      },
      entries,
    },
    null,
    2
  );

  if (check) {
    let bad = false;
    if (fs.existsSync(mdPath) && fs.readFileSync(mdPath, "utf8") !== md) {
      console.error("docs/IPC_INVENTORY.md is out of date. Run: node scripts/generate-ipc-inventory.js");
      bad = true;
    }
    if (fs.existsSync(jsonPath) && fs.readFileSync(jsonPath, "utf8") !== `${json}\n` && fs.readFileSync(jsonPath, "utf8") !== json) {
      const existing = fs.readFileSync(jsonPath, "utf8").trim();
      if (existing !== json.trim()) {
        console.error("governance/ipc_inventory.json is out of date. Run: node scripts/generate-ipc-inventory.js");
        bad = true;
      }
    }
    if (!fs.existsSync(mdPath) || !fs.existsSync(jsonPath)) {
      console.error("Missing inventory files. Run: node scripts/generate-ipc-inventory.js");
      process.exit(1);
    }
    if (bad) process.exit(1);
    console.log("✓ IPC inventory files match src/main.js");
    return;
  }

  fs.mkdirSync(path.dirname(mdPath), { recursive: true });
  fs.writeFileSync(mdPath, md, "utf8");
  fs.writeFileSync(jsonPath, `${json}\n`, "utf8");
  console.log(`Wrote ${path.relative(root, mdPath)} and ${path.relative(root, jsonPath)} (${entries.length} channels).`);
}

main();

