/**
 * Cross-cutting logo pulse for the NeuralShell mark (toolbar + future surfaces).
 * Decouples App/chat from TopStatusBar via a tiny window event.
 */
export const NEURALSHELL_LOGO_CUE_EVENT = 'neuralshell:logo-cue';

/** @typedef {'transmit'|'receive'|'error'|'boot'|'session'} NeuralShellLogoCueKind */

/**
 * @param {NeuralShellLogoCueKind} kind
 * @param {Record<string, unknown>} [extra]
 */
export function dispatchNeuralShellLogoCue(kind, extra = {}) {
    if (typeof window === 'undefined') return;
    window.dispatchEvent(new CustomEvent(NEURALSHELL_LOGO_CUE_EVENT, { detail: { kind, ...extra } }));
}

import React, { useEffect, useMemo, useState } from 'react';

/**
 * NeuralShellLogo — shell + core mark with event-driven motion.
 *
 * - Idle: stable “locked” pose (no background timer).
 * - thinking: slow dashed-ring drift (CSS, low CPU).
 * - cue (transmit / receive / error / boot): short timeline tied to chat + lifecycle.
 */

const LOOP_MS = 3600;

function clamp(value, min = 0, max = 1) {
    return Math.min(max, Math.max(min, value));
}

function mix(start, end, amount) {
    return start + (end - start) * amount;
}

function easeOutCubic(value) {
    const safe = clamp(value);
    return 1 - ((1 - safe) ** 3);
}

function easeInOutSine(value) {
    const safe = clamp(value);
    return -(Math.cos(Math.PI * safe) - 1) / 2;
}

function windowProgress(time, start, end) {
    return clamp((time - start) / Math.max(1, end - start));
}

/** @typedef {'neutral'|'success'|'danger'} LogoTint */

/**
 * @param {number} elapsedMs
 * @param {number} s
 * @param {{ tint?: LogoTint }} [opts]
 */
function sampleLogoAt(elapsedMs, s, opts = {}) {
    const tint = opts.tint || 'neutral';
    const cx = s / 2;
    const cy = s / 2;

    const approach = easeOutCubic(windowProgress(elapsedMs, 0, 950));
    const impact = windowProgress(elapsedMs, 950, 1300);
    const bloom = easeInOutSine(windowProgress(elapsedMs, 1300, 2300));
    const orbit = windowProgress(elapsedMs, 2300, LOOP_MS);
    const orbitalT = ((elapsedMs - 1300) / 900) * Math.PI * 2;

    const shellTravelX = mix(cx + s * 0.72, cx - s * 0.08, approach);
    const shellTravelY = mix(cy - s * 0.12, cy - s * 0.02, approach);
    const shellRotate = mix(-18, 8, approach);
    const shellSettleY = mix(shellTravelY, cy + s * 0.20, bloom * 0.55 + orbit * 0.45);
    const shellSettleScale = mix(1, 0.86, bloom * 0.6 + orbit * 0.4);
    const impactFlash = Math.sin(impact * Math.PI);
    const impactRing = easeOutCubic(impact);
    const coreGlow = mix(2.2, 7.5, bloom);
    const corePulse = 0.5 + (Math.sin(((elapsedMs - 1300) / 300) * Math.PI) * 0.5);

    let frameGlow = bloom > 0.05 || orbit > 0.05 ? 'rgba(34,211,238,0.26)' : impact > 0 ? 'rgba(217,119,87,0.34)' : 'rgba(107,122,255,0.18)';
    let impactFill = '#D97757';
    let impactStroke = '#D97757';
    if (tint === 'success') {
        frameGlow = bloom > 0.05 ? 'rgba(52,211,153,0.38)' : 'rgba(16,185,129,0.22)';
        impactFill = 'rgba(52,211,153,0.55)';
        impactStroke = '#34d399';
    } else if (tint === 'danger') {
        frameGlow = 'rgba(248,113,113,0.35)';
        impactFill = 'rgba(248,113,113,0.65)';
        impactStroke = '#f87171';
    }

    const orbitRadius = s * 0.20;
    const orbitNodes = [0, 1, 2].map((index) => {
        const angle = orbitalT + (index / 3) * Math.PI * 2;
        return {
            x: cx + Math.cos(angle) * orbitRadius,
            y: cy + Math.sin(angle) * orbitRadius * 0.72,
            r: index === 0 ? 1.45 : 1.05,
            color: index === 0 ? '#67e8f9' : index === 1 ? '#4ade80' : '#c4b5fd',
        };
    });
    const traceOpacity = mix(0.2, 0.9, bloom * 0.75 + orbit * 0.25);
    const scanSweepX = mix(cx - s * 0.18, cx + s * 0.18, (Math.sin(orbitalT * 0.5) + 1) / 2);

    const shellOpacity = tint === 'danger' && impact > 0.55 ? mix(0.96, 0.35, (impact - 0.55) / 0.45) : 0.96;

    return {
        cx,
        cy,
        s,
        approach,
        impact,
        bloom,
        orbit,
        shellTravelX,
        shellTravelY,
        shellRotate,
        shellSettleY,
        shellSettleScale,
        impactFlash,
        impactRing,
        coreGlow,
        corePulse,
        frameGlow,
        impactFill,
        impactStroke,
        orbitNodes,
        traceOpacity,
        scanSweepX,
        orbitalT,
        shellOpacity,
    };
}

const CUE_MS = {
    transmit: 820,
    receive: 980,
    error: 640,
    boot: 2400,
    session: 1100,
};

const NeuralShellLogo = React.memo(function NeuralShellLogo({
    size = 40,
    className = '',
    animationsEnabled = true,
    thinking = false,
    cueKey = 0,
    cueKind = null,
}) {
    const [cueDrive, setCueDrive] = useState(null);
    const [reduceMotion, setReduceMotion] = useState(false);

    useEffect(() => {
        if (typeof window === 'undefined' || !window.matchMedia) return;
        const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
        const apply = () => setReduceMotion(Boolean(mq.matches));
        apply();
        mq.addEventListener?.('change', apply);
        return () => mq.removeEventListener?.('change', apply);
    }, []);

    useEffect(() => {
        if (!cueKind || !animationsEnabled || reduceMotion) {
            setCueDrive(null);
            return;
        }
        const duration = CUE_MS[cueKind] || CUE_MS.transmit;
        let cancelled = false;
        const start = performance.now();
        const tick = (now) => {
            if (cancelled) return;
            const t = Math.min(1, (now - start) / duration);
            setCueDrive({ kind: cueKind, t });
            if (t < 1) requestAnimationFrame(tick);
            else setCueDrive(null);
        };
        requestAnimationFrame(tick);
        return () => { cancelled = true; };
    }, [cueKey, cueKind, animationsEnabled, reduceMotion]);

    const settledMs = LOOP_MS - 280;

    const virtualElapsed = useMemo(() => {
        if (!animationsEnabled || reduceMotion) return settledMs;
        if (!cueDrive) return settledMs;
        const { kind, t } = cueDrive;
        const te = easeOutCubic(t);
        if (kind === 'transmit') return mix(0, 1280, te);
        if (kind === 'receive') return mix(1050, LOOP_MS - 40, te);
        if (kind === 'error') return mix(880, 1320, te);
        if (kind === 'boot') return t * LOOP_MS;
        if (kind === 'session') return mix(LOOP_MS * 0.35, LOOP_MS * 0.92, te);
        return settledMs;
    }, [cueDrive, animationsEnabled, reduceMotion, settledMs]);

    const tint = useMemo(() => {
        if (!cueDrive) return 'neutral';
        if (cueDrive.kind === 'receive') return 'success';
        if (cueDrive.kind === 'error') return 'danger';
        return 'neutral';
    }, [cueDrive]);

    const frame = useMemo(
        () => sampleLogoAt(virtualElapsed, size, { tint }),
        [virtualElapsed, size, tint],
    );

    const {
        cx,
        cy,
        s,
        approach,
        impact,
        bloom,
        orbit,
        shellTravelX,
        shellTravelY,
        shellRotate,
        shellSettleY,
        shellSettleScale,
        impactFlash,
        impactRing,
        coreGlow,
        corePulse,
        frameGlow,
        impactFill,
        impactStroke,
        orbitNodes,
        traceOpacity,
        scanSweepX,
        shellOpacity,
    } = frame;

    const showOrbitNodes = (bloom > 0.08 || orbit > 0) && (!cueDrive || cueDrive.kind !== 'error' || cueDrive.t > 0.35);
    const thinkingRing = Boolean(thinking && animationsEnabled && !reduceMotion && !cueDrive);

    return (
        <svg
            width={s}
            height={s}
            viewBox={`0 0 ${s} ${s}`}
            className={`select-none ${className}`}
            style={{ overflow: 'visible' }}
            data-ns-logo-thinking={thinkingRing ? 'true' : 'false'}
            aria-hidden="true"
        >
            <defs>
                <filter id="ns-glow" x="-50%" y="-50%" width="200%" height="200%">
                    <feGaussianBlur stdDeviation={coreGlow} result="blur" />
                    <feMerge>
                        <feMergeNode in="blur" />
                        <feMergeNode in="SourceGraphic" />
                    </feMerge>
                </filter>
                <filter id="ns-flash" x="-100%" y="-100%" width="300%" height="300%">
                    <feGaussianBlur stdDeviation="4" />
                </filter>
                <filter id="ns-bullet-glow" x="-60%" y="-60%" width="220%" height="220%">
                    <feGaussianBlur stdDeviation="1.5" result="b" />
                    <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
                </filter>
                <radialGradient id="ns-core-fill" cx="45%" cy="42%" r="58%">
                    <stop offset="0%" stopColor="#0f1c2d" />
                    <stop offset="45%" stopColor="#0a1320" />
                    <stop offset="100%" stopColor="#05070d" />
                </radialGradient>
                <linearGradient id="ns-shell-head" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" stopColor="#ffd8c0" />
                    <stop offset="45%" stopColor="#d97757" />
                    <stop offset="100%" stopColor="#7f3f2e" />
                </linearGradient>
                <linearGradient id="ns-shell-brass" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#fcd34d" />
                    <stop offset="52%" stopColor="#b8860b" />
                    <stop offset="100%" stopColor="#7a5500" />
                </linearGradient>
                <linearGradient id="ns-core-trace" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#4ade80" stopOpacity="0" />
                    <stop offset="50%" stopColor="#67e8f9" stopOpacity="1" />
                    <stop offset="100%" stopColor="#c4b5fd" stopOpacity="0" />
                </linearGradient>
                <linearGradient id="ns-scan" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#67e8f9" stopOpacity="0" />
                    <stop offset="50%" stopColor="#67e8f9" stopOpacity="0.75" />
                    <stop offset="100%" stopColor="#67e8f9" stopOpacity="0" />
                </linearGradient>
                <linearGradient id="ns-ring" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" stopColor="rgba(103,232,249,0.9)" />
                    <stop offset="45%" stopColor="rgba(167,139,250,0.72)" />
                    <stop offset="100%" stopColor="rgba(74,222,128,0.72)" />
                </linearGradient>
            </defs>

            <circle
                className={thinkingRing ? 'ns-logo-orbit-dash' : ''}
                cx={cx}
                cy={cy}
                r={s * 0.46}
                fill="none"
                stroke={frameGlow}
                strokeWidth="0.95"
                strokeDasharray="3.6 2.6"
                opacity="0.85"
            />

            <circle
                cx={cx}
                cy={cy}
                r={s * 0.40}
                fill="none"
                stroke="url(#ns-ring)"
                strokeWidth="0.95"
                strokeOpacity={0.48 + bloom * 0.28}
            />

            <circle
                cx={cx} cy={cy} r={s * 0.38}
                fill={impactFill}
                opacity={impactFlash * 0.72}
                filter="url(#ns-flash)"
                style={{ transition: 'opacity 0.12s ease-out' }}
            />

            <g filter="url(#ns-glow)">
                <circle cx={cx} cy={cy} r={s * 0.23} fill="url(#ns-core-fill)" stroke="#67e8f9" strokeOpacity={0.55 + bloom * 0.25} strokeWidth="0.85" />
                <circle cx={cx} cy={cy} r={s * 0.13} fill="rgba(103,232,249,0.10)" stroke="rgba(103,232,249,0.45)" strokeWidth="0.7" />
                <circle cx={cx} cy={cy} r={s * (0.045 + corePulse * 0.015)} fill="#c4f1ff" opacity={0.9} />
                <path
                    d={`M ${cx - s * 0.08} ${cy + s * 0.10} L ${cx - s * 0.08} ${cy - s * 0.10} L ${cx + s * 0.02} ${cy + s * 0.02} L ${cx + s * 0.02} ${cy - s * 0.10} L ${cx + s * 0.08} ${cy - s * 0.10} L ${cx + s * 0.08} ${cy + s * 0.10}`}
                    fill="none"
                    stroke="rgba(196,241,255,0.78)"
                    strokeWidth="0.72"
                    strokeLinejoin="round"
                    strokeLinecap="round"
                    opacity={0.62 + bloom * 0.25}
                />
                <path d={`M ${cx - s * 0.17} ${cy - s * 0.04} C ${cx - s * 0.05} ${cy - s * 0.16} ${cx + s * 0.03} ${cy - s * 0.16} ${cx + s * 0.15} ${cy - s * 0.04}`} fill="none" stroke="url(#ns-core-trace)" strokeWidth="0.8" strokeOpacity={traceOpacity} strokeLinecap="round" />
                <path d={`M ${cx - s * 0.15} ${cy + s * 0.04} C ${cx - s * 0.03} ${cy + s * 0.15} ${cx + s * 0.06} ${cy + s * 0.12} ${cx + s * 0.16} ${cy + s * 0.02}`} fill="none" stroke="url(#ns-core-trace)" strokeWidth="0.78" strokeOpacity={traceOpacity * 0.9} strokeLinecap="round" />
                <path d={`M ${cx} ${cy - s * 0.16} L ${cx} ${cy + s * 0.16}`} fill="none" stroke="rgba(103,232,249,0.38)" strokeWidth="0.65" strokeOpacity={0.45 + bloom * 0.2} strokeLinecap="round" />
                <rect x={scanSweepX - s * 0.035} y={cy - s * 0.18} width={s * 0.07} height={s * 0.36} rx={s * 0.03} fill="url(#ns-scan)" opacity={0.45 + orbit * 0.2} />
            </g>

            <g
                transform={`translate(${shellTravelX}, ${shellSettleY}) rotate(${shellRotate}) scale(${shellSettleScale})`}
                filter="url(#ns-bullet-glow)"
                opacity={shellOpacity}
            >
                <path
                    d="M 0 -6.7 C 1.15 -5.05 1.7 -3.45 1.7 -1.8 L -1.7 -1.8 C -1.7 -3.45 -1.15 -5.05 0 -6.7 Z"
                    fill="url(#ns-shell-head)"
                />
                <rect x="-1.7" y="-1.8" width="3.4" height="4.5" rx="0.35" fill="url(#ns-shell-head)" />
                <rect x="-2.15" y="2.55" width="4.3" height="5.2" rx="0.65" fill="url(#ns-shell-brass)" />
                <line x1="-1.8" y1="3.55" x2="1.8" y2="3.55" stroke="rgba(122,85,0,0.36)" strokeWidth="0.42" />
                <line x1="-1.8" y1="4.8" x2="1.8" y2="4.8" stroke="rgba(122,85,0,0.26)" strokeWidth="0.42" />
                <circle cx="0" cy="7.35" r="1.38" fill="#d2a52d" />
                <circle cx="0" cy="7.35" r="0.46" fill="#7a5500" />
                <rect x="-2.3" y="7.05" width="4.6" height="0.55" rx="0.2" fill="#7a5500" fillOpacity="0.72" />
                <line x1="-0.65" y1="2.9" x2="-0.85" y2="7" stroke="rgba(255,237,160,0.42)" strokeWidth="0.54" strokeLinecap="round" />
            </g>

            {approach < 0.98 && (
                <g opacity={0.24 + approach * 0.3}>
                    {[1, 2, 3].map((index) => {
                        const trailX = shellTravelX + index * 4.8;
                        const trailY = mix(cy - s * 0.10, cy - s * 0.02, approach) + index * 1.2;
                        return (
                            <line
                                key={`trail-${index}`}
                                x1={trailX}
                                y1={trailY}
                                x2={trailX + 3.2}
                                y2={trailY + 1.2}
                                stroke={index === 1 ? '#fca5a5' : '#fcd34d'}
                                strokeWidth={1.15 - index * 0.18}
                                strokeOpacity={0.52 - index * 0.1}
                                strokeLinecap="round"
                            />
                        );
                    })}
                </g>
            )}

            {impact > 0 && (
                <circle
                    cx={cx} cy={cy}
                    r={mix(s * 0.12, s * 0.34, impactRing)}
                    fill="none"
                    stroke={impactStroke}
                    strokeWidth={mix(1.35, 0.25, impactRing)}
                    strokeOpacity={0.7 - impactRing * 0.7}
                />
            )}

            {showOrbitNodes && orbitNodes.map((node, index) => (
                <g key={`orbit-${['primary', 'secondary', 'tertiary'][index]}`}>
                    <line x1={cx} y1={cy} x2={node.x} y2={node.y} stroke="rgba(103,232,249,0.12)" strokeWidth="0.5" />
                    <circle cx={node.x} cy={node.y} r={node.r} fill={node.color} opacity={0.9} />
                </g>
            ))}

        </svg>
    );
});

export default NeuralShellLogo;

