        connectionHealthPrev.current = connectionHealth;
        return;
    }
    const prev = connectionHealthPrev.current;
    if (prev === connectionHealth) return;
    connectionHealthPrev.current = connectionHealth;
    if (connectionHealth === 'online' && prev === 'offline') bumpLogoCue('online');
    if (connectionHealth === 'offline' && prev !== 'offline') bumpLogoCue('offline');
}, [connectionHealth, animationsEnabled, bumpLogoCue]);

const bootLogoRef = React.useRef(false);
React.useEffect(() => {
    if (animationsEnabled === false || bootLogoRef.current) return;
    bootLogoRef.current = true;
    const id = window.setTimeout(() => bumpLogoCue('boot'), 500);
    return () => window.clearTimeout(id);
}, [animationsEnabled, bumpLogoCue]);

