import React, { useEffect, useId, useMemo, useState } from 'react';

/**
 * NeuralShellLogo — kinetic shell mark, “maximum drama” edition.
 *
 * Idle is still cheap (no timer). Cues run on rAF. Thinking uses CSS halos + ring drift.
 * Respects prefers-reduced-motion (falls back to settled pose).
 */

const LOOP_MS = 3600;

function clamp(value, min = 0, max = 1) {
    return Math.min(max, Math.max(min, value));
}

function mix(start, end, amount) {
    return start + (end - start) * amount;
}

function easeOutCubic(value) {
    const safe = clamp(value);
    return 1 - ((1 - safe) ** 3);
}

function easeInOutSine(value) {
    const safe = clamp(value);
    return -(Math.cos(Math.PI * safe) - 1) / 2;
}

function easeOutBack(value) {
    const x = clamp(value);
    const c1 = 1.70158;
    const c3 = c1 + 1;
    return 1 + c3 * ((x - 1) ** 3) + c1 * ((x - 1) ** 2);
}

function windowProgress(time, start, end) {
    return clamp((time - start) / Math.max(1, end - start));
}

/** @typedef {'neutral'|'success'|'danger'} LogoTint */

/**
 * @param {number} elapsedMs
 * @param {number} s
 * @param {{ tint?: LogoTint }} [opts]
 */
function sampleLogoAt(elapsedMs, s, opts = {}) {
    const tint = opts.tint || 'neutral';
    const cx = s / 2;
    const cy = s / 2;

    const approach = easeOutCubic(windowProgress(elapsedMs, 0, 950));
    const impact = windowProgress(elapsedMs, 950, 1300);
    const bloom = easeInOutSine(windowProgress(elapsedMs, 1300, 2300));
    const orbit = windowProgress(elapsedMs, 2300, LOOP_MS);
    const orbitalT = ((elapsedMs - 1300) / 900) * Math.PI * 2;

    const shellTravelX = mix(cx + s * 0.72, cx - s * 0.08, approach);
    const shellTravelY = mix(cy - s * 0.12, cy - s * 0.02, approach);
    const shellRotate = mix(-28, 12, approach);
    const shellSettleY = mix(shellTravelY, cy + s * 0.20, bloom * 0.55 + orbit * 0.45);
    const shellSettleScale = mix(1, 0.86, bloom * 0.6 + orbit * 0.4);
    const impactFlash = Math.sin(impact * Math.PI);
    const impactRing = easeOutCubic(impact);
    const coreGlow = mix(2.4, 9.2, bloom);
    const corePulse = 0.5 + (Math.sin(((elapsedMs - 1300) / 260) * Math.PI) * 0.5);

    let frameGlow = bloom > 0.05 || orbit > 0.05 ? 'rgba(34,211,238,0.32)' : impact > 0 ? 'rgba(217,119,87,0.42)' : 'rgba(107,122,255,0.22)';
    let impactFill = '#D97757';
    let impactStroke = '#D97757';
    if (tint === 'success') {
        frameGlow = bloom > 0.05 ? 'rgba(52,211,153,0.48)' : 'rgba(16,185,129,0.28)';
        impactFill = 'rgba(52,211,153,0.62)';
        impactStroke = '#34d399';
    } else if (tint === 'danger') {
        frameGlow = 'rgba(248,113,113,0.48)';
        impactFill = 'rgba(248,113,113,0.78)';
        impactStroke = '#f87171';
    }

    const orbitRadius = s * 0.22;
    const orbitNodes = [0, 1, 2, 3, 4, 5].map((index) => {
        const angle = orbitalT + (index / 6) * Math.PI * 2;
        const rMul = index % 2 === 0 ? 1 : 0.88;
        return {
            x: cx + Math.cos(angle) * orbitRadius * rMul,
            y: cy + Math.sin(angle) * orbitRadius * 0.72 * rMul,
            r: index === 0 ? 1.55 : index < 3 ? 1.12 : 0.92,
            color: index % 3 === 0 ? '#67e8f9' : index % 3 === 1 ? '#4ade80' : '#c4b5fd',
        };
    });
    const traceOpacity = mix(0.25, 0.95, bloom * 0.75 + orbit * 0.25);
    const scanSweepX = mix(cx - s * 0.22, cx + s * 0.22, (Math.sin(orbitalT * 0.55) + 1) / 2);

    const shellOpacity = tint === 'danger' && impact > 0.48 ? mix(0.98, 0.28, (impact - 0.48) / 0.52) : 0.98;

    return {
        cx,
        cy,
        s,
        approach,
        impact,
        bloom,
        orbit,
        shellTravelX,
        shellTravelY,
        shellRotate,
        shellSettleY,
        shellSettleScale,
        impactFlash,
        impactRing,
        coreGlow,
        corePulse,
        frameGlow,
        impactFill,
        impactStroke,
        orbitNodes,
        traceOpacity,
        scanSweepX,
        orbitalT,
        shellOpacity,
    };
}

const CUE_MS = {
    transmit: 1040,
    receive: 1380,
    error: 920,
    boot: 3600,
    session: 1280,
    online: 880,
    offline: 960,
};

const NeuralShellLogo = React.memo(function NeuralShellLogo({
    size = 40,
    className = '',
    animationsEnabled = true,
    thinking = false,
    cueKey = 0,
    cueKind = null,
}) {
    const reactId = useId().replace(/:/g, '');
    const gid = `nsl-${reactId}`;

    const [cueDrive, setCueDrive] = useState(null);
    const [reduceMotion, setReduceMotion] = useState(false);

    useEffect(() => {
        if (typeof window === 'undefined' || !window.matchMedia) return;
        const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
        const apply = () => setReduceMotion(Boolean(mq.matches));
        apply();
        mq.addEventListener?.('change', apply);
        return () => mq.removeEventListener?.('change', apply);
    }, []);

    useEffect(() => {
        if (!cueKind || !animationsEnabled || reduceMotion) {
            setCueDrive(null);
            return;
        }
        const duration = CUE_MS[cueKind] || CUE_MS.transmit;
        let cancelled = false;
        const start = performance.now();
        const tick = (now) => {
            if (cancelled) return;
            const t = Math.min(1, (now - start) / duration);
            setCueDrive({ kind: cueKind, t });
            if (t < 1) requestAnimationFrame(tick);
            else setCueDrive(null);
        };
        requestAnimationFrame(tick);
        return () => { cancelled = true; };
    }, [cueKey, cueKind, animationsEnabled, reduceMotion]);

    const settledMs = LOOP_MS - 280;

    const virtualElapsed = useMemo(() => {
        if (!animationsEnabled || reduceMotion) return settledMs;
        if (!cueDrive) return settledMs;
        const { kind, t } = cueDrive;
        const te = easeOutCubic(t);
        const teBack = easeOutBack(t);
        if (kind === 'transmit') return mix(0, 1320, teBack);
        if (kind === 'receive') return mix(980, LOOP_MS - 20, te);
        if (kind === 'error') return mix(820, 1380, te);
        if (kind === 'boot') return t * LOOP_MS;
        if (kind === 'session') return mix(LOOP_MS * 0.28, LOOP_MS * 0.94, te);
        if (kind === 'online') return mix(settledMs - 260, LOOP_MS - 40, te);
        if (kind === 'offline') return mix(880, 1350, te);
        return settledMs;
    }, [cueDrive, animationsEnabled, reduceMotion, settledMs]);

    const tint = useMemo(() => {
        if (!cueDrive) return 'neutral';
        if (cueDrive.kind === 'receive' || cueDrive.kind === 'online') return 'success';
        if (cueDrive.kind === 'error' || cueDrive.kind === 'offline') return 'danger';
        return 'neutral';
    }, [cueDrive]);

    const frame = useMemo(
        () => sampleLogoAt(virtualElapsed, size, { tint }),
        [virtualElapsed, size, tint],
    );

    const {
        cx,
        cy,
        s,
        approach,
        impact,
        bloom,
        orbit,
        shellTravelX,
        shellTravelY,
        shellRotate,
        shellSettleY,
        shellSettleScale,
        impactFlash,
        impactRing,
        coreGlow,
        corePulse,
        frameGlow,
        impactFill,
        impactStroke,
        orbitNodes,
        traceOpacity,
        scanSweepX,
        shellOpacity,
    } = frame;

    const tCue = cueDrive ? cueDrive.t : 0;
    const kindCue = cueDrive ? cueDrive.kind : null;

    const showOrbitNodes = (bloom > 0.06 || orbit > 0) && (!cueDrive || cueDrive.kind !== 'error' || cueDrive.t > 0.28);
    const thinkingRing = Boolean(thinking && animationsEnabled && !reduceMotion && !cueDrive);

    const transmitSparks = useMemo(() => {
        if (!cueDrive || cueDrive.kind !== 'transmit' || reduceMotion) return [];
        const t = cueDrive.t;
        const n = 14;
        const sparks = [];
        for (let i = 0; i < n; i += 1) {
            const ang = (i / n) * Math.PI * 2 + t * 9;
            const mag = mix(s * 0.58, s * 0.1, easeOutCubic(t)) * (0.85 + 0.15 * Math.sin(i * 1.7));
            sparks.push({
                x: cx + Math.cos(ang) * mag,
                y: cy + Math.sin(ang) * mag * 0.82,
                op: (1 - t) * 0.9,
                r: 1.1 + (i % 4) * 0.35,
            });
        }
        return sparks;
    }, [cueDrive, s, cx, cy, reduceMotion]);

    const shockRings = useMemo(() => {
        if (!cueDrive || reduceMotion) return [];
        const t = cueDrive.t;
        const k = cueDrive.kind;
        if (k === 'receive' || k === 'online') {
            return [0, 1, 2].map((i) => ({
                r: s * (0.14 + (t * 0.42) + i * 0.07),
                op: (1 - t) * (0.55 - i * 0.14) * (k === 'online' ? 0.85 : 1),
                sw: 2.2 - i * 0.45,
            }));
        }
        if (k === 'error' || k === 'offline') {
            return [0, 1, 2, 3].map((i) => ({
                r: s * (0.12 + easeOutCubic(Math.min(1, t * 1.4)) * 0.38 + i * 0.055),
                op: (1 - t * 0.85) * (0.5 - i * 0.1),
                sw: 2.4 - i * 0.35,
            }));
        }
        if (k === 'transmit' && t > 0.35 && t < 0.92) {
            const u = (t - 0.35) / 0.57;
            return [{
                r: s * (0.16 + u * 0.28),
                op: (1 - u) * 0.45,
                sw: 2,
            }];
        }
        return [];
    }, [cueDrive, s, reduceMotion]);

    const wrapClass = [
        'relative inline-flex rounded-full',
        thinkingRing ? 'ns-logo-wrap-thinking' : '',
        kindCue === 'error' || kindCue === 'offline' ? 'ns-logo-wrap-error' : '',
        kindCue === 'transmit' ? 'ns-logo-wrap-transmit' : '',
        kindCue === 'receive' || kindCue === 'online' ? 'ns-logo-wrap-receive' : '',
        kindCue === 'boot' ? 'ns-logo-wrap-boot' : '',
        cueDrive ? 'ns-logo-cue-active' : '',
    ].filter(Boolean).join(' ');

    const glitchActive = Boolean(
        !reduceMotion && cueDrive && (cueDrive.kind === 'error' || cueDrive.kind === 'offline') && cueDrive.t > 0.02 && cueDrive.t < 0.78,
    );

    return (
        <span
            className={`${wrapClass} ${className}`}
            style={{ width: s, height: s }}
            data-ns-cue={kindCue || undefined}
            data-ns-thinking={thinkingRing ? 'true' : 'false'}
        >
            {glitchActive && (
                <svg
                    className="pointer-events-none absolute inset-0 ns-logo-chroma-a"
                    width={s}
                    height={s}
                    viewBox={`0 0 ${s} ${s}`}
                    aria-hidden="true"
                >
                    <circle cx={cx + 0.9} cy={cy - 0.6} r={s * 0.2} fill="rgba(244,114,182,0.22)" />
                </svg>
            )}
            {glitchActive && (
                <svg
                    className="pointer-events-none absolute inset-0 ns-logo-chroma-b"
                    width={s}
                    height={s}
                    viewBox={`0 0 ${s} ${s}`}
                    aria-hidden="true"
                >
                    <circle cx={cx - 0.8} cy={cy + 0.7} r={s * 0.18} fill="rgba(34,211,238,0.2)" />
                </svg>
            )}

            <svg
                width={s}
                height={s}
                viewBox={`0 0 ${s} ${s}`}
                className="relative z-[1] select-none"
                style={{ overflow: 'visible' }}
                data-ns-logo-thinking={thinkingRing ? 'true' : 'false'}
                aria-hidden="true"
            >
                <defs>
                    <filter id={`${gid}-glow`} x="-80%" y="-80%" width="260%" height="260%">
                        <feGaussianBlur stdDeviation={coreGlow} result="blur" />
                        <feMerge>
                            <feMergeNode in="blur" />
                            <feMergeNode in="SourceGraphic" />
                        </feMerge>
                    </filter>
                    <filter id={`${gid}-flash`} x="-100%" y="-100%" width="300%" height="300%">
                        <feGaussianBlur stdDeviation="5" />
                    </filter>
                    <filter id={`${gid}-bullet`} x="-80%" y="-80%" width="260%" height="260%">
                        <feGaussianBlur stdDeviation="2" result="b" />
                        <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
                    </filter>
                    <radialGradient id={`${gid}-core`} cx="45%" cy="42%" r="58%">
                        <stop offset="0%" stopColor="#0f1c2d" />
                        <stop offset="45%" stopColor="#0a1320" />
                        <stop offset="100%" stopColor="#05070d" />
                    </radialGradient>
                    <linearGradient id={`${gid}-shell-head`} x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stopColor="#ffd8c0" />
                        <stop offset="45%" stopColor="#d97757" />
                        <stop offset="100%" stopColor="#7f3f2e" />
                    </linearGradient>
                    <linearGradient id={`${gid}-shell-brass`} x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" stopColor="#fcd34d" />
                        <stop offset="52%" stopColor="#b8860b" />
                        <stop offset="100%" stopColor="#7a5500" />
                    </linearGradient>
                    <linearGradient id={`${gid}-trace`} x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" stopColor="#4ade80" stopOpacity="0" />
                        <stop offset="50%" stopColor="#67e8f9" stopOpacity="1" />
                        <stop offset="100%" stopColor="#c4b5fd" stopOpacity="0" />
                    </linearGradient>
                    <linearGradient id={`${gid}-scan`} x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" stopColor="#67e8f9" stopOpacity="0" />
                        <stop offset="50%" stopColor="#a5f3fc" stopOpacity="0.9" />
                        <stop offset="100%" stopColor="#67e8f9" stopOpacity="0" />
                    </linearGradient>
                    <linearGradient id={`${gid}-ring`} x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stopColor="rgba(103,232,249,0.95)" />
                        <stop offset="45%" stopColor="rgba(167,139,250,0.8)" />
                        <stop offset="100%" stopColor="rgba(74,222,128,0.78)" />
                    </linearGradient>
                    <radialGradient id={`${gid}-halo`} cx="50%" cy="50%" r="50%">
                        <stop offset="0%" stopColor="rgba(103,232,249,0.35)" />
                        <stop offset="55%" stopColor="rgba(107,122,255,0.12)" />
                        <stop offset="100%" stopColor="rgba(0,0,0,0)" />
                    </radialGradient>
                </defs>

                {thinkingRing && (
                    <circle cx={cx} cy={cy} r={s * 0.52} fill={`url(#${gid}-halo)`} opacity="0.55" className="ns-logo-halo-breathe" />
                )}

                {shockRings.map((ring, idx) => (
                    <circle
                        key={`shock-${idx}-${kindCue}`}
                        cx={cx}
                        cy={cy}
                        r={ring.r}
                        fill="none"
                        stroke={tint === 'danger' || kindCue === 'offline' ? '#f87171' : '#34d399'}
                        strokeWidth={ring.sw}
                        strokeOpacity={ring.op}
                    />
                ))}

                <circle
                    className={thinkingRing ? 'ns-logo-orbit-dash' : ''}
                    cx={cx}
                    cy={cy}
                    r={s * 0.46}
                    fill="none"
                    stroke={frameGlow}
                    strokeWidth={thinkingRing ? 1.15 : 0.95}
                    strokeDasharray={thinkingRing ? '4 3' : '3.6 2.6'}
                    opacity="0.9"
                />

                {thinkingRing && (
                    <circle
                        className="ns-logo-orbit-dash-rev"
                        cx={cx}
                        cy={cy}
                        r={s * 0.505}
                        fill="none"
                        stroke="rgba(167,139,250,0.35)"
                        strokeWidth="0.65"
                        strokeDasharray="2 5"
                        opacity="0.75"
                    />
                )}

                <circle
                    cx={cx}
                    cy={cy}
                    r={s * 0.40}
                    fill="none"
                    stroke={`url(#${gid}-ring)`}
                    strokeWidth="0.95"
                    strokeOpacity={0.5 + bloom * 0.32 + (kindCue === 'boot' ? tCue * 0.12 : 0)}
                />

                <circle
                    cx={cx} cy={cy} r={s * 0.38}
                    fill={impactFill}
                    opacity={impactFlash * 0.78}
                    filter={`url(#${gid}-flash)`}
                />

                <g filter={`url(#${gid}-glow)`}>
                    <circle cx={cx} cy={cy} r={s * 0.23} fill={`url(#${gid}-core)`} stroke="#67e8f9" strokeOpacity={0.55 + bloom * 0.3} strokeWidth="0.85" />
                    <circle cx={cx} cy={cy} r={s * 0.13} fill="rgba(103,232,249,0.12)" stroke="rgba(103,232,249,0.5)" strokeWidth="0.7" />
                    <circle cx={cx} cy={cy} r={s * (0.045 + corePulse * 0.02)} fill="#e0f2fe" opacity={0.92} />
                    <path
                        d={`M ${cx - s * 0.08} ${cy + s * 0.10} L ${cx - s * 0.08} ${cy - s * 0.10} L ${cx + s * 0.02} ${cy + s * 0.02} L ${cx + s * 0.02} ${cy - s * 0.10} L ${cx + s * 0.08} ${cy - s * 0.10} L ${cx + s * 0.08} ${cy + s * 0.10}`}
                        fill="none"
                        stroke="rgba(196,241,255,0.82)"
                        strokeWidth="0.72"
                        strokeLinejoin="round"
                        strokeLinecap="round"
                        opacity={0.64 + bloom * 0.28}
                    />
