import { create } from 'zustand';
import { persist } from 'zustand/middleware';

const DEFAULTS = {
    theme: 'default',
    bubbleStyle: 'bubble',
    density: 'normal',
    showTimestamps: false,
    showAvatars: true,
    codeLineNumbers: true,
    animateMessages: true,
    quickReplyEnabled: true,
};

export const useChatAppearanceStore = create(
    persist(
        (set) => ({
            ...DEFAULTS,
            update: (key, value) => set((prev) => ({ ...prev, [key]: value })),
            reset: () => set({ ...DEFAULTS }),
        }),
        {
            name: 'neuralshell_chat_theme_v1',
            partialize: (s) => ({
                theme: s.theme,
                bubbleStyle: s.bubbleStyle,
                density: s.density,
                showTimestamps: s.showTimestamps,
                showAvatars: s.showAvatars,
                codeLineNumbers: s.codeLineNumbers,
                animateMessages: s.animateMessages,
                quickReplyEnabled: s.quickReplyEnabled,
            }),
        },
    ),
);

/** Stable selectors for message rows */
export function selectChatDensityGap(state) {
    const d = state.density || 'normal';
    if (d === 'compact') return '0.5rem';
    if (d === 'relaxed') return '1.5rem';
    if (d === 'spacious') return '2rem';
    return '1rem';
}

export function selectChatBodyFontPx(state) {
    const d = state.density || 'normal';
    if (d === 'compact') return '11px';
    if (d === 'relaxed') return '14px';
    if (d === 'spacious') return '15px';
    return '13px';
}

