export function hotkeyComboMatches(combo: string, e: KeyboardEvent): boolean {
    if (!combo || !e) return false;
    const parsed = parseCombo(combo);
    const eventKeyNorm = e.key === ' ' ? 'Space' : e.key === ',' ? ',' : e.key;
    return (
        parsed.ctrl === (e.ctrlKey || e.metaKey)
        && parsed.shift === e.shiftKey
        && parsed.alt === e.altKey
        && parsed.key.toLowerCase() === eventKeyNorm.toLowerCase()
    );
}

/** True when the current event matches the saved chord for an action id. */
export function hotkeyActionMatches(actionId: string, e: KeyboardEvent): boolean {
    const id = String(actionId || '').trim();
    if (!id) return false;
    const row = loadBindings().find((b) => b.id === id);
    if (!row || !row.keys) return false;
    return hotkeyComboMatches(row.keys, e);
}

