import React, { useRef, useMemo } from 'react';
import { useModalAccessibility } from '../hooks/useModalAccessibility.js';
import { useHotkeyBindings, formatKeysForDisplay } from '../hooks/useHotkeys';

function bindingLabel(bindings, id, fallback) {
    const row = bindings.find((b) => b.id === id);
    return row ? formatKeysForDisplay(row.keys) : fallback;
}

function keysFromCombo(combo) {
    return String(combo || '').split('+').map((p) => p.trim()).filter(Boolean);
}

function Key({ label }) {
    const isSlash = String(label).startsWith('/');
    return (
        <kbd
            className={`inline-flex items-center justify-center rounded px-1.5 py-0.5 text-[10px] font-mono border ${
                isSlash
                    ? 'border-amber-500/30 bg-amber-500/10 text-amber-200 min-w-[3rem]'
                    : 'border-white/[0.10] bg-white/[0.05] text-slate-300 min-w-[1.4rem]'
            }`}
        >
            {label}
        </kbd>
    );
}

const KeyboardShortcutsModal = React.memo(function KeyboardShortcutsModal({ open, onClose }) {
    const panelRef = useRef(null);
    const { bindings } = useHotkeyBindings();
    useModalAccessibility(open, panelRef, onClose, { initialSelector: '[data-kbd-modal-close="true"]' });

    const bk = (id, fb) => bindingLabel(bindings, id, fb);

    const sections = useMemo(() => [
        {
            title: 'Global',
            color: 'text-violet-400',
            dot: 'bg-violet-500',
            shortcuts: [
                { keys: keysFromCombo(bk('newChat', 'Ctrl+N')), desc: 'New chat / session (rebind in Settings → Keyboard)' },
                { keys: keysFromCombo(bk('spotlight', 'Ctrl+Space')), desc: 'Spotlight' },
                { keys: keysFromCombo(bk('palette', 'Ctrl+K')), desc: 'Command palette (skipped while typing in composer)' },
                { keys: keysFromCombo(bk('searchBar', 'Ctrl+F')), desc: 'Search messages in conversation' },
                { keys: keysFromCombo(bk('settings', 'Ctrl+,')), desc: 'Open Settings' },
                { keys: ['Ctrl', '?'], desc: 'This shortcuts reference' },
                { keys: ['Esc'], desc: 'Cancel streaming / close overlay' },
            ],
        },
        {
            title: 'Panels',
            color: 'text-sky-400',
            dot: 'bg-sky-500',
            shortcuts: [
                { keys: keysFromCombo(bk('commandCenter', 'Ctrl+Shift+K')), desc: 'Command Center' },
                { keys: keysFromCombo(bk('taskManager', 'Ctrl+Shift+T')), desc: 'Task Manager' },
                { keys: ['Ctrl', 'Shift', 'H'], desc: 'Prompt History' },
                { keys: keysFromCombo(bk('sessionPinboard', 'Ctrl+Shift+N')), desc: 'Session Pinboard' },
                { keys: keysFromCombo(bk('stickyNotes', 'Ctrl+Shift+Y')), desc: 'Sticky Notes' },
                { keys: ['Ctrl', 'Shift', 'R'], desc: 'LLM Rules' },
                { keys: ['Ctrl', 'Shift', 'E'], desc: 'Runtime Event Feed' },
                { keys: ['Ctrl', 'Shift', 'P'], desc: 'Operator Progress' },
                { keys: ['Ctrl', 'Shift', 'F'], desc: 'Focus Mode' },
            ],
        },
        {
            title: 'Workspace',
            color: 'text-emerald-400',
            dot: 'bg-emerald-500',
            shortcuts: [
                { keys: ['Ctrl', 'Shift', 'V'], desc: 'Smart Clipboard' },
                { keys: ['Ctrl', 'Shift', 'S'], desc: 'Flush SmartSuggest cache' },
                { keys: ['Ctrl', 'B'], desc: 'Open Bookmarks' },
                { keys: ['Ctrl', 'G'], desc: 'Neural Graph' },
                { keys: ['↑'], desc: 'Recall last sent message in composer' },
                { keys: ['Ctrl', 'T'], desc: 'Session Templates — quick-start prompts' },
                { keys: ['Ctrl', 'Shift', 'J'], desc: 'Session Notes — per-session notepad' },
                { keys: ['? (hold)'], desc: 'Shortcut Cheat Sheet — quick keyboard reference' },
            ],
        },
        {
            title: 'Slash Commands',
            color: 'text-amber-400',
            dot: 'bg-amber-500',
            shortcuts: [
                { keys: ['/help'], desc: 'Full command reference' },
                { keys: ['/stats'], desc: 'Deep session analytics' },
                { keys: ['/cost'], desc: 'AI Cost Estimator — token pricing for current model' },
                { keys: ['/search'], desc: 'Quick message search (also bound in Settings)' },
                { keys: ['/shortcuts'], desc: 'Shortcut Cheat Sheet (also hold ?)' },
                { keys: ['/density'], desc: 'Message Density Bar — visual mini-map of chat' },
                { keys: ['/dna'], desc: 'Conversation DNA — genetic algorithm evolving communication patterns' },
                { keys: ['/pomodoro [N]'], desc: 'Pomodoro focus timer — default 25 min' },
                { keys: ['/insights'], desc: 'Conversation Insights — stats, words, timing' },
                { keys: ['/snapshot [label]'], desc: 'Save chat snapshot to a restore slot' },
                { keys: ['/snapshots'], desc: 'Open Session Snapshots panel' },
                { keys: ['/calc <expr>'], desc: 'Inline math calculator' },
                { keys: ['/recap'], desc: 'Narrative session recap' },
                { keys: ['/compress'], desc: 'Compress old messages, free context tokens' },
                { keys: ['/diff'], desc: 'Prompt Diff — compare 2 variants side-by-side' },
                { keys: ['/remind N msg'], desc: 'Set in-session message-count reminder' },
                { keys: ['/actions'], desc: 'Custom actions bar guide' },
                { keys: ['/canvas'], desc: 'Canvas Mode — spatial view' },
                { keys: ['/focus'], desc: 'Focus / Zen Mode' },
                { keys: ['/export'], desc: 'Export session (MD / HTML / JSON)' },
                { keys: ['/rules'], desc: 'LLM Behavior Rules' },
                { keys: ['/history'], desc: 'Prompt History drawer' },
                { keys: ['/xp'], desc: 'Operator XP & tier panel' },
                { keys: ['/rewind'], desc: 'Session Rewind playback' },
                { keys: ['/notes'], desc: 'Session Notes panel' },
                { keys: ['/templates'], desc: 'Session Templates picker' },
                { keys: ['/keyboard'], desc: 'Keyboard shortcuts reference' },
                { keys: ['/clear'], desc: 'Clear current session' },
                { keys: ['/whoami'], desc: 'Operator profile card' },
            ],
        },
    ], [bindings]);

    if (!open) return null;

    return (
        <>
            <div className="fixed inset-0 z-[230] bg-black/65 backdrop-blur-sm animate-in fade-in duration-200" onClick={onClose} aria-hidden="true" />
            <div
                ref={panelRef}
                role="dialog"
                aria-modal="true"
                aria-labelledby="keyboard-shortcuts-title"
                className="fixed top-12 left-1/2 -translate-x-1/2 z-[231] w-full max-w-2xl rounded-2xl border border-white/[0.08] bg-slate-950/98 shadow-[0_28px_70px_rgba(0,0,0,0.75)] overflow-hidden flex flex-col animate-in zoom-in-95 fade-in duration-200 motion-reduce:animate-none"
                style={{ maxHeight: 'calc(100vh - 80px)' }}
            >
                {/* Header */}
                <div className="flex items-center justify-between px-5 py-3.5 border-b border-white/[0.06]">
                    <div className="flex items-center gap-2.5">
                        <div className="w-6 h-6 rounded-lg bg-violet-500/15 border border-violet-500/25 flex items-center justify-center">
                            <svg className="w-3.5 h-3.5 text-violet-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                                <rect x="2" y="4" width="20" height="16" rx="2" />
                                <path d="M6 8h.01M10 8h.01M14 8h.01M18 8h.01M8 12h.01M12 12h.01M16 12h.01M6 16h4M14 16h4" />
                            </svg>
                        </div>
                        <div>
                            <h2 id="keyboard-shortcuts-title" className="text-[13px] font-semibold text-slate-200">Keyboard Shortcuts</h2>
                            <div className="text-[10px] text-slate-600 font-mono">Ctrl+? to toggle · many chords are editable in Settings</div>
                        </div>
                    </div>
                    <button
                        type="button"
                        data-kbd-modal-close="true"
                        data-accessible-overlay-close
                        onClick={onClose}
                        aria-label="Close keyboard shortcuts"
                        title="Close"
                        className="w-7 h-7 rounded-lg flex items-center justify-center text-slate-600 hover:text-slate-300 hover:bg-white/[0.06] transition-all text-[11px]"
                    >
                        <span aria-hidden="true">✕</span>
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 min-h-0 overflow-y-auto custom-scrollbar p-5">
                    <div className="grid grid-cols-2 gap-5">
                        {sections.map((section) => (
                            <div key={section.title}>
                                <h3 className={`flex items-center gap-1.5 mb-2.5 text-[10px] uppercase tracking-[0.14em] font-bold ${section.color}`}>
                                    <span className={`w-1.5 h-1.5 rounded-full ${section.dot}`} aria-hidden="true" />
                                    {section.title}
                                </h3>
                                <div className="space-y-1.5">
                                    {section.shortcuts.map((sc, i) => (
                                        <div key={i} className="flex items-center justify-between gap-3 px-2 py-1.5 rounded-lg hover:bg-white/[0.04] transition-colors duration-150">
                                            <span className="text-[11px] text-slate-400 flex-1 min-w-0">{sc.desc}</span>
                                            <div className="flex items-center gap-1 shrink-0">
                                                {sc.keys.map((k, ki) => (
                                                    <React.Fragment key={ki}>
                                                        <Key label={k} />
                                                        {ki < sc.keys.length - 1 && !String(sc.keys[0]).startsWith('/') && (
                                                            <span className="text-[9px] text-slate-700">+</span>
                                                        )}
                                                    </React.Fragment>
                                                ))}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Footer */}
                <div className="px-5 py-2.5 border-t border-white/[0.04] bg-black/20 flex items-center justify-between">
                    <span className="text-[9px] font-mono text-slate-700">NeuralShell · Keyboard Reference</span>
                    <span className="text-[9px] font-mono text-slate-700">Press Esc or Ctrl+? to close</span>
                </div>
            </div>
        </>
    );
});

export default KeyboardShortcutsModal;

