function PlayheadJump({ messageCount, currentIndex, onJump }) {
    const [draft, setDraft] = useState(String(currentIndex + 1));

    React.useEffect(() => {
        setDraft(String(currentIndex + 1));
    }, [currentIndex]);

    const apply = useCallback(() => {
        const n = Number.parseInt(String(draft).trim(), 10);
        if (!Number.isFinite(n)) return;
        const idx = Math.max(0, Math.min(messageCount - 1, n - 1));
        onJump(idx);
    }, [draft, messageCount, onJump]);

    const onKeyDown = useCallback((e) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            apply();
        }
    }, [apply]);

    if (messageCount < 1) return null;

    return (
        <div className="flex flex-wrap items-center justify-center gap-2 px-3 py-2 rounded-xl border border-violet-500/15 bg-violet-500/[0.04]">
            <span className="text-[10px] font-mono text-violet-300/90 uppercase tracking-widest">Lock to #</span>
            <input
                type="number"
                min={1}
                max={messageCount}
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                onKeyDown={onKeyDown}
                aria-label="Message number to lock playhead (1-based)"
