const PARSE_COMBO_CACHE = new Map<string, { ctrl: boolean; shift: boolean; alt: boolean; meta: boolean; key: string }>();
const PARSE_COMBO_CACHE_MAX = 64;

function parseCombo(combo: string): { ctrl: boolean; shift: boolean; alt: boolean; meta: boolean; key: string } {
    const hit = PARSE_COMBO_CACHE.get(combo);
    if (hit) return hit;
    const parts = combo.split('+').map((p) => p.trim());
    const parsed = {
        ctrl: parts.includes('Ctrl'),
        shift: parts.includes('Shift'),
        alt: parts.includes('Alt'),
        meta: parts.includes('Meta'),
        key: parts.filter((p) => !['Ctrl', 'Shift', 'Alt', 'Meta'].includes(p))[0] || '',
    };
    if (PARSE_COMBO_CACHE.size >= PARSE_COMBO_CACHE_MAX) {
        PARSE_COMBO_CACHE.clear();
    }
    PARSE_COMBO_CACHE.set(combo, parsed);
    return parsed;
}

