/**
 * Contract: renderer hotkey hook stays allocation-light on the keydown path
 * (tear style — node assert, no jest).
 */
const fs = require("fs");
const path = require("path");
const assert = require("assert");

function run() {
  const hookPath = path.join(__dirname, "..", "src", "renderer", "src", "hooks", "useHotkeys.ts");
  const src = fs.readFileSync(hookPath, "utf8");

  assert(src.includes("bindingKeyById"), "useHotkeys must define bindingKeyById for O(1) action lookup");
  assert(src.includes("function commitBindings"), "useHotkeys must use commitBindings to sync map + array");
  assert(
    /export function getHotkeyBindings\(\)[\s\S]*?return loadBindings\(\)/.test(src),
    "getHotkeyBindings must return loadBindings() without per-call .map clone"
  );
  assert(
    src.includes("PARSE_COMBO_CACHE"),
    "useHotkeys must cache parseCombo results for repeat modifier matching"
  );
  assert(
    src.includes("export function hotkeyActionMatches"),
    "hotkeyActionMatches must remain the App/TopStatusBar entry point"
  );

  console.log("PASS renderer-hotkey-path");
}

run();

