function ScrubberRail({ messages, currentIndex, onScrub, onHover }) {
    const railRef = useRef(null);
    const hoverRafRef = useRef(null);
    const pendingHoverRef = useRef(null);

    const handleClick = useCallback((e) => {
        if (!railRef.current) return;
        const rect = railRef.current.getBoundingClientRect();
        const ratio = (e.clientX - rect.left) / rect.width;
        const idx = Math.round(ratio * (messages.length - 1));
        onScrub(Math.max(0, Math.min(idx, messages.length - 1)));
    }, [messages.length, onScrub]);

    const flushHover = useCallback(() => {
        hoverRafRef.current = null;
        const idx = pendingHoverRef.current;
        pendingHoverRef.current = null;
        if (typeof onHover === 'function' && idx !== null) {
            onHover(idx);
        }
    }, [onHover]);

    const handleMouseMove = useCallback((e) => {
        if (!railRef.current || typeof onHover !== 'function') return;
        const rect = railRef.current.getBoundingClientRect();
        const ratio = (e.clientX - rect.left) / rect.width;
        const idx = Math.max(0, Math.min(messages.length - 1, Math.round(ratio * (messages.length - 1))));
        pendingHoverRef.current = idx;
        if (hoverRafRef.current == null) {
            hoverRafRef.current = requestAnimationFrame(flushHover);
        }
    }, [messages.length, onHover, flushHover]);

    useEffect(() => () => {
        if (hoverRafRef.current != null) {
            cancelAnimationFrame(hoverRafRef.current);
        }
    }, []);

    const handleMouseLeave = useCallback(() => {
        if (hoverRafRef.current != null) {
            cancelAnimationFrame(hoverRafRef.current);
            hoverRafRef.current = null;
        }
        pendingHoverRef.current = null;
        if (typeof onHover === 'function') onHover(null);
    }, [onHover]);

    const progress = messages.length > 1 ? currentIndex / (messages.length - 1) : 0;

    return (
        <div
            ref={railRef}
            className="relative w-full h-8 cursor-pointer group"
            onClick={handleClick}
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
        >

