import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';

/** Same key as `ScratchpadTab` — drafts stay in sync with the workspace rail. */
const STORAGE_DRAFT = 'scratchpadDraft';
const STORAGE_CODE = 'neuralshell_scratchpad_code_v1';

function readKey(key) {
    if (typeof window === 'undefined' || !window.localStorage) return '';
    try {
        return String(window.localStorage.getItem(key) || '');
    } catch {
        return '';
    }
}

function writeKey(key, value) {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try {
        window.localStorage.setItem(key, String(value ?? ''));
    } catch {
        /* best effort */
    }
}

function leaveScratchpadRoute() {
    const { pathname } = window.location;
    if (pathname === '/scratchpad' || pathname.endsWith('/scratchpad')) {
        const next = pathname.replace(/\/?scratchpad\/?$/, '') || '/';
        window.history.replaceState({}, '', next + (window.location.search || ''));
    } else {
        const base = String(window.location.pathname || '/') + String(window.location.search || '');
        window.history.replaceState({}, '', `${base}#`);
    }
    window.dispatchEvent(new CustomEvent('neuralshell:route'));
}

function countLines(text) {
    if (!text) return 0;
    return String(text).split(/\r\n|\r|\n/).length;
}

/**
 * Full-window scratch lab for prompts, snippets, and throwaway code.
 * Open via `#/scratchpad` or `/scratchpad` (see `routes.ts`).
 */
export default function ScratchpadPage() {
    const [tab, setTab] = useState('draft');
    const [draft, setDraft] = useState('');
    const [code, setCode] = useState('');
    const areaRef = useRef(null);

    const storageKey = tab === 'code' ? STORAGE_CODE : STORAGE_DRAFT;
    const text = tab === 'code' ? code : draft;
    const setText = tab === 'code' ? setCode : setDraft;

    useEffect(() => {
        setDraft(readKey(STORAGE_DRAFT));
        setCode(readKey(STORAGE_CODE));
    }, []);

    useEffect(() => {
        writeKey(STORAGE_DRAFT, draft);
    }, [draft]);

    useEffect(() => {
        writeKey(STORAGE_CODE, code);
    }, [code]);

    const stats = useMemo(() => ({
        chars: text.length,
        lines: countLines(text),
    }), [text]);

    const handleCopy = useCallback(async () => {
        try {
            await navigator.clipboard.writeText(text);
        } catch {
            window.prompt('Copy manually:', text);
        }
    }, [text]);

    const handleDownload = useCallback(() => {
        const ext = tab === 'code' ? 'js' : 'txt';
        const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `neuralshell-scratchpad-${tab}.${ext}`;
        a.click();
        URL.revokeObjectURL(url);
    }, [tab, text]);

    const handleClear = useCallback(() => {
        if (!text.trim()) return;
        if (!window.confirm(`Clear the ${tab === 'code' ? 'code' : 'draft'} buffer? This cannot be undone.`)) return;
        setText('');
        writeKey(storageKey, '');
    }, [setText, storageKey, tab, text]);

    return (
        <div
            data-testid="scratchpad-page"
            className="min-h-screen flex flex-col bg-[#07070c] text-slate-200 antialiased"
            style={{ fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace' }}
        >
            <header className="shrink-0 border-b border-cyan-500/15 bg-slate-950/90 backdrop-blur-md px-4 py-3 flex flex-wrap items-center justify-between gap-3">
                <div>
                    <h1 className="text-sm font-black tracking-tight text-transparent bg-clip-text bg-gradient-to-r from-cyan-300 via-violet-300 to-fuchsia-300">
                        Scratchpad Lab
                    </h1>
                    <p className="text-[10px] font-mono text-slate-500 mt-0.5">
                        Local-only buffers · not sent to the model until you copy them into chat
                    </p>
                </div>
                <div className="flex items-center gap-2 flex-wrap">
                    <div className="flex rounded-lg border border-white/[0.08] overflow-hidden">
                        <button
                            type="button"
                            data-testid="scratchpad-tab-draft"
                            onClick={() => setTab('draft')}
                            className={`px-3 py-1.5 text-[11px] font-semibold transition-colors ${
                                tab === 'draft' ? 'bg-cyan-500/20 text-cyan-200' : 'text-slate-500 hover:text-slate-300'
                            }`}
                        >
                            Draft
                        </button>
                        <button
                            type="button"
                            data-testid="scratchpad-tab-code"
                            onClick={() => setTab('code')}
                            className={`px-3 py-1.5 text-[11px] font-semibold transition-colors ${
                                tab === 'code' ? 'bg-violet-500/20 text-violet-200' : 'text-slate-500 hover:text-slate-300'
                            }`}
                        >
                            Code
                        </button>
                    </div>
                    <button
                        type="button"
                        onClick={handleCopy}
                        className="px-2.5 py-1.5 rounded-lg border border-white/10 text-[11px] text-slate-300 hover:bg-white/[0.06]"
                    >
                        Copy all
                    </button>
                    <button
                        type="button"
                        onClick={handleDownload}
                        className="px-2.5 py-1.5 rounded-lg border border-white/10 text-[11px] text-slate-300 hover:bg-white/[0.06]"
                    >
                        Download
                    </button>
                    <button
                        type="button"
                        onClick={handleClear}
                        disabled={!text}
                        className="px-2.5 py-1.5 rounded-lg border border-rose-500/25 text-[11px] text-rose-300/90 hover:bg-rose-500/10 disabled:opacity-40"
                    >
                        Clear
                    </button>
                    <button
                        type="button"
                        data-testid="scratchpad-back-workspace"
                        onClick={leaveScratchpadRoute}
                        className="px-3 py-1.5 rounded-lg border border-cyan-400/30 bg-cyan-500/10 text-[11px] font-semibold text-cyan-200 hover:bg-cyan-500/20"
                    >
                        ← Workspace
                    </button>
                </div>
            </header>

            <div className="shrink-0 px-4 py-1.5 border-b border-white/[0.05] flex items-center justify-between text-[10px] font-mono text-slate-600">
                <span>
                    {stats.lines} lines · {stats.chars} chars · {storageKey}
                </span>
                <span className="text-slate-700">Tab · indent as needed · no execution</span>
            </div>

            <div className="flex-1 min-h-0 p-3 sm:p-4">
                <textarea
                    ref={areaRef}
                    data-testid="scratchpad-page-editor"
                    value={text}
                    onChange={(e) => setText(e.target.value)}
                    spellCheck={tab === 'draft'}
                    placeholder={
                        tab === 'code'
                            ? '// throwaway JS/TS, JSON, shell…\n// use Draft for long prompts'
                            : 'Prompts, checklists, API payloads, meeting notes…'
                    }
                    className="w-full h-[min(100%,calc(100vh-9rem))] min-h-[320px] rounded-xl border border-white/10 bg-black/50 px-3 py-3 text-[13px] leading-relaxed text-slate-200 outline-none focus:border-cyan-400/35 focus:ring-1 focus:ring-cyan-400/20 resize-y"
                />
            </div>
        </div>
    );
}

