/**
 * Shell extension registry — minimal SDK for Operator Home tiles.
 * Sources: bundled JSON, optional /shell-extensions/registry.json, user localStorage import.
 */

export const SHELL_EXTENSIONS_STORAGE_KEY = 'neuralshell_shell_extensions_registry_v1';

const SAFE_PANEL = /^[a-z0-9][a-z0-9_-]{0,62}$/i;
const SAFE_EXT_ID = /^[a-z0-9][a-z0-9._-]{0,120}$/i;

function safeString(v, max = 200) {
    const s = String(v ?? '').trim();
    if (!s) return '';
    return s.length > max ? s.slice(0, max) : s;
}

function normalizeAction(raw) {
    if (!raw || typeof raw !== 'object') return null;
    const type = String(raw.type || '').trim().toLowerCase();
    if (type === 'open-panel' || type === 'panel') {
        const panel = String(raw.panel || '').trim();
        if (!SAFE_PANEL.test(panel)) return null;
        const method = String(raw.method || 'open').toLowerCase() === 'toggle' ? 'toggle' : 'open';
        return { type: 'panel', panel, method };
    }
    if (type === 'set-hash' || type === 'hash') {
        let h = String(raw.hash || '').trim();
        if (!h.startsWith('#')) h = `#${h}`;
        if (!/^#[#/a-zA-Z0-9_-]{1,128}$/.test(h)) return null;
        return { type: 'hash', hash: h };
    }
    if (type === 'signal' || type === 'slash') {
        const text = safeString(raw.text ?? raw.command, 500);
        if (!text) return null;
        return { type: 'signal', text };
    }
    return null;
}

function normalizeTile(extId, extName, raw) {
    if (!raw || typeof raw !== 'object') return null;
    const id = safeString(raw.id, 80);
    const label = safeString(raw.label, 80);
    if (!id || !label) return null;
    const action = normalizeAction(raw.action);
    if (!action) return null;
    return {
        id: `${extId}::${id}`,
        label,
        subtitle: safeString(raw.subtitle, 120) || undefined,
        icon: safeString(raw.icon, 8) || '◇',
        source: 'extension',
        extensionId: extId,
        extensionName: extName,
        action,
    };
}

function normalizeExtension(raw) {
    if (!raw || typeof raw !== 'object') return null;
    const id = safeString(raw.id, 120);
    if (!SAFE_EXT_ID.test(id)) return null;
    const name = safeString(raw.name, 120) || id;
    const tilesIn = Array.isArray(raw.tiles) ? raw.tiles : [];
    const tiles = [];
    tilesIn.forEach((t) => {
        const nt = normalizeTile(id, name, t);
        if (nt) tiles.push(nt);
    });
    return { id, name, tiles };
}

/**
 * @param {unknown} raw
 * @returns {{ schemaVersion: number, extensions: ReturnType<typeof normalizeExtension>[] }}
 */
export function parseShellExtensionRegistry(raw) {
    if (!raw || typeof raw !== 'object') return { schemaVersion: 1, extensions: [] };
    const schemaVersion = Number(raw.schemaVersion) || 1;
    const list = Array.isArray(raw.extensions) ? raw.extensions : [];
    const extensions = [];
    list.forEach((e) => {
        const ne = normalizeExtension(e);
        if (ne && ne.tiles.length) extensions.push(ne);
    });
    return { schemaVersion, extensions };
}

export function loadUserShellExtensionRegistry() {
    if (typeof window === 'undefined' || !window.localStorage) {
        return { schemaVersion: 1, extensions: [] };
    }
    try {
        const raw = JSON.parse(window.localStorage.getItem(SHELL_EXTENSIONS_STORAGE_KEY) || 'null');
        return parseShellExtensionRegistry(raw);
    } catch {
        return { schemaVersion: 1, extensions: [] };
    }
}

export function saveUserShellExtensionRegistry(registry) {
    if (typeof window === 'undefined' || !window.localStorage) return false;
    try {
        const body = JSON.stringify(registry);
        if (body.length > 800_000) return false;
        window.localStorage.setItem(SHELL_EXTENSIONS_STORAGE_KEY, body);
        return true;
    } catch {
        return false;
    }
}

/** Merge user registry with a single new extension (replace same id). */
export function upsertUserExtension(extensionRecord) {
    const cur = loadUserShellExtensionRegistry();
    const next = normalizeExtension(extensionRecord);
    if (!next || !next.tiles.length) return { ok: false, error: 'Invalid extension or no valid tiles.' };
    const others = cur.extensions.filter((e) => e.id !== next.id);
    const merged = { schemaVersion: 1, extensions: [...others, next] };
    if (!saveUserShellExtensionRegistry(merged)) return { ok: false, error: 'Could not persist (quota or storage).' };
    return { ok: true, registry: merged };
}

/**
 * @param {{ bundled?: unknown, remote?: unknown, user?: ReturnType<typeof loadUserShellExtensionRegistry> }} sources
 */
export function collectExtensionHomeTiles(sources = {}) {
    const out = [];
    const bundled = parseShellExtensionRegistry(sources.bundled);
    bundled.extensions.forEach((e) => e.tiles.forEach((t) => out.push(t)));
    if (sources.remote) {
        const remote = parseShellExtensionRegistry(sources.remote);
        remote.extensions.forEach((e) => e.tiles.forEach((t) => out.push(t)));
    }
    const user = sources.user || loadUserShellExtensionRegistry();
    user.extensions.forEach((e) => e.tiles.forEach((t) => out.push(t)));
    return out;
}

export async function fetchPublicShellExtensionRegistry(baseUrl) {
    const base = String(baseUrl || '/').replace(/\/?$/, '/');
    const url = `${base}shell-extensions/registry.json`;
    const res = await fetch(url, { cache: 'no-store' });
    if (!res.ok) return null;
    const data = await res.json();
    return parseShellExtensionRegistry(data);
}

