/**
 * Paged launcher (snap scroll) + extension tiles + JSON import.
 */
export default function OperatorHomeOverlay({
    open,
    onClose,
    onOpenPanel,
    onOpenScratchpadRail,
    bundledRegistry,
    remoteRegistry,
    userRev,
    onUserExtensionsChanged,
}) {
    const panelRef = useRef(null);
    const scrollerRef = useRef(null);
    const [pageIndex, setPageIndex] = useState(0);
    const [importError, setImportError] = useState('');
    const [importOk, setImportOk] = useState('');

    useModalAccessibility(open, panelRef, onClose);

    const extensionTiles = useMemo(
        () => collectExtensionHomeTiles({
            bundled: bundledRegistry,
            remote: remoteRegistry,
            user: loadUserShellExtensionRegistry(),
        }),
        [bundledRegistry, remoteRegistry, userRev],
    );

    const pages = useMemo(() => {
        const extPage = {
            id: 'extensions',
            title: 'Extensions',
            tiles: extensionTiles,
            isExtensionsPage: true,
        };
        return [...BUILTIN_PAGES, extPage];
    }, [extensionTiles]);

    useEffect(() => {
        if (!open) return;
        setPageIndex(0);
        setImportError('');
        setImportOk('');
        const el = scrollerRef.current;
        if (el) el.scrollTo({ left: 0, behavior: 'instant' in window ? 'instant' : 'auto' });
    }, [open]);

    const scrollToPage = useCallback((idx) => {
        const el = scrollerRef.current;
        if (!el) return;
        const w = el.clientWidth;
        el.scrollTo({ left: idx * w, behavior: 'smooth' });
        setPageIndex(idx);
    }, []);

    useEffect(() => {
        if (!open) return undefined;
        const el = scrollerRef.current;
        if (!el) return undefined;
        const onScroll = () => {
            const w = el.clientWidth || 1;
            const i = Math.round(el.scrollLeft / w);
            setPageIndex(Math.max(0, Math.min(i, pages.length - 1)));
        };
        el.addEventListener('scroll', onScroll, { passive: true });
        return () => el.removeEventListener('scroll', onScroll);
    }, [open, pages.length]);

    const handleActivate = useCallback((tile) => {
        const action = tile && tile.action;
        if (!action || typeof action !== 'object') return;
        const type = String(action.type || '').toLowerCase();
        if (type === 'noop') return;
        if (type === 'scratchpad-rail' || action.type === 'scratchpad-rail') {
            onOpenScratchpadRail();
            onClose();
            return;
        }
        if (type === 'panel') {
            const panel = String(action.panel || '');
            const method = String(action.method || 'open').toLowerCase() === 'toggle' ? 'toggle' : 'open';
            onOpenPanel(panel, method);
            onClose();
            return;
        }
        if (type === 'hash') {
            const h = String(action.hash || '').trim();
            if (h.startsWith('#')) {
                window.location.hash = h;
                window.dispatchEvent(new CustomEvent('neuralshell:route'));
            }
            onClose();
            return;
        }
        if (type === 'signal') {
            const text = String(action.text || '').trim();
            if (text) {
                window.dispatchEvent(new CustomEvent('neuralshell:execute-signal', { detail: { text } }));
            }
            onClose();
        }
    }, [onClose, onOpenPanel, onOpenScratchpadRail]);

    const onPickImport = useCallback((e) => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        setImportError('');
        setImportOk('');
        const reader = new FileReader();
        reader.onload = () => {
            try {
                const raw = JSON.parse(String(reader.result || '{}'));
                const ext = raw.extensions ? raw : raw.tiles ? raw : null;
                const single = raw && raw.id && Array.isArray(raw.tiles) ? raw : null;
                const payload = single || (ext && ext.extensions && ext.extensions[0]) || raw;
                const res = upsertUserExtension(payload);
                if (!res.ok) {
                    setImportError(res.error || 'Import failed');
                    return;
                }
                setImportOk(`Installed “${payload.name || payload.id}”.`);
                if (typeof onUserExtensionsChanged === 'function') onUserExtensionsChanged();
            } catch (err) {
                setImportError(err && err.message ? err.message : 'Invalid JSON');
            }
        };
        reader.readAsText(file, 'utf8');
        e.target.value = '';
    }, [onUserExtensionsChanged]);

    if (!open) return null;

    return (
        <div
            className="fixed inset-0 z-[10050] flex flex-col bg-[#07070d]/98 backdrop-blur-md"
            role="dialog"
            aria-modal="true"
            aria-labelledby="operator-home-title"
        >
            <div ref={panelRef} className="flex min-h-0 flex-1 flex-col">
                <header className="flex shrink-0 items-center justify-between gap-3 border-b border-white/10 px-4 py-3">
                    <div>
                        <h1 id="operator-home-title" className="text-sm font-bold uppercase tracking-[0.18em] text-cyan-200/95">
                            Operator home
                        </h1>
                        <p className="text-[10px] font-mono text-slate-500 mt-0.5">Swipe or use dots · tiles open tools then return here via /home</p>
                    </div>
                    <button
                        type="button"
                        data-accessible-overlay-close
                        onClick={onClose}
                        className="rounded-lg border border-white/15 px-3 py-1.5 text-[10px] font-mono uppercase tracking-wider text-slate-200 hover:bg-white/10"
                    >
                        ← Workspace
                    </button>
                </header>

                <div
                    ref={scrollerRef}
                    className="min-h-0 flex-1 overflow-x-auto overflow-y-hidden flex snap-x snap-mandatory scroll-smooth"
                    style={{ WebkitOverflowScrolling: 'touch' }}
                >
                    {pages.map((page) => (
                        <section
                            key={page.id}
                            className="snap-start shrink-0 w-full min-h-0 flex flex-col px-4 py-3 box-border"
                            aria-label={page.title}
                        >
                            <h2 className="text-[11px] font-mono uppercase tracking-[0.14em] text-slate-400 mb-3 shrink-0">
                                {page.title}
                            </h2>
                            <div className="min-h-0 flex-1 overflow-y-auto pr-1">
                                {page.isExtensionsPage && page.tiles.length === 0 ? (
                                    <p className="text-xs text-slate-500 font-mono max-w-md">
                                        No extension tiles yet. Ship JSON in <code className="text-cyan-400/90">public/shell-extensions/registry.json</code>, or import a pack below.
                                    </p>
                                ) : null}
                                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2 pb-4">
                                    {page.tiles.map((tile) => (
                                        <TileButton key={tile.id} tile={tile} onActivate={handleActivate} />
                                    ))}
                                </div>
                                {page.isExtensionsPage ? (
                                    <div className="mt-2 rounded-xl border border-violet-400/20 bg-violet-950/20 p-3 space-y-2">
                                        <div className="text-[10px] font-mono uppercase tracking-wider text-violet-200/90">Import extension pack (JSON)</div>
                                        <p className="text-[9px] text-slate-500 leading-relaxed">
                                            Schema: {'{'} &quot;id&quot;, &quot;name&quot;, &quot;tiles&quot;: [ {'{'} &quot;id&quot;, &quot;label&quot;, &quot;action&quot;: {'{'} &quot;type&quot;: &quot;open-panel&quot;, &quot;panel&quot;: &quot;command-center&quot; {'}' } {'}'} ] {'}'}. Optional: &quot;method&quot;: &quot;toggle&quot;. Also: type signal + text, or hash + hash.
                                        </p>
                                        <label className="inline-flex cursor-pointer rounded-lg border border-violet-300/30 bg-black/30 px-3 py-2 text-[10px] font-mono text-violet-100 hover:bg-violet-500/10">
                                            <input type="file" accept="application/json,.json" className="sr-only" onChange={onPickImport} />
                                            Choose file…
                                        </label>
                                        {importError ? <div className="text-[10px] text-rose-300 font-mono">{importError}</div> : null}
                                        {importOk ? <div className="text-[10px] text-emerald-300 font-mono">{importOk}</div> : null}
                                    </div>
                                ) : null}
                            </div>
                        </section>
                    ))}
                </div>

                <footer className="shrink-0 border-t border-white/10 px-4 py-3 flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                    <div className="flex items-center justify-center gap-1.5">
                        {pages.map((p, i) => (
                            <button
                                key={p.id}
                                type="button"
                                aria-label={`Page ${i + 1}: ${p.title}`}
                                aria-current={i === pageIndex ? 'true' : undefined}
                                onClick={() => scrollToPage(i)}
                                className={`h-2.5 w-2.5 rounded-full transition ${i === pageIndex ? 'bg-cyan-400 w-6' : 'bg-white/20 hover:bg-white/35'}`}
                            />
                        ))}
                    </div>
                    <div className="flex justify-center gap-2">
                        <button
                            type="button"
                            disabled={pageIndex <= 0}
                            onClick={() => scrollToPage(pageIndex - 1)}
                            className="rounded-lg border border-white/10 px-3 py-1 text-[10px] font-mono uppercase text-slate-300 disabled:opacity-30 hover:bg-white/5"
                        >
                            ← Prev
                        </button>
                        <button
                            type="button"
                            disabled={pageIndex >= pages.length - 1}
                            onClick={() => scrollToPage(pageIndex + 1)}
                            className="rounded-lg border border-white/10 px-3 py-1 text-[10px] font-mono uppercase text-slate-300 disabled:opacity-30 hover:bg-white/5"
                        >
                            Next →
                        </button>
                    </div>
                </footer>
            </div>
        </div>
    );
}

