import React from 'react';
import { useModalAccessibility } from '../hooks/useModalAccessibility.js';

const CanvasMode = React.memo(function CanvasMode({ open, onClose, chatLog }) {
    const messages = Array.isArray(chatLog) ? chatLog : [];
    const [cards, setCards] = React.useState([]);
    const [dragging, setDragging] = React.useState(null);
    const [pan, setPan] = React.useState({ x: 0, y: 0 });
    const [connecting, setConnecting] = React.useState(null);
    const [connections, setConnections] = React.useState([]);
    const [canvasPanning, setCanvasPanning] = React.useState(false);
    const dragOffset = React.useRef({ x: 0, y: 0 });
    const panDragRef = React.useRef(null);
    const openSessionRef = React.useRef(false);
    const canvasRef = React.useRef(null);
    const panelRef = React.useRef(null);
    useModalAccessibility(open, panelRef, onClose, { initialSelector: '[data-testid="canvas-mode-close"]' });

    React.useEffect(() => {
        if (!open) {
            openSessionRef.current = false;
            setCards([]);
            setConnections([]);
            setPan({ x: 0, y: 0 });
            setDragging(null);
            setConnecting(null);
            setCanvasPanning(false);
            panDragRef.current = null;
            return;
        }
        if (openSessionRef.current) return;
        openSessionRef.current = true;
        const filtered = messages.filter((m) => m && !m._streaming);
        const initial = filtered.map((msg, i) => ({
            id: `card-${i}`,
            role: msg.role,
            content: String(msg.content || '').slice(0, 300),
            x: 80 + (i % 4) * 280,
            y: 60 + Math.floor(i / 4) * 200,
            width: 240,
        }));
        setCards(initial);
        const conns = [];
        for (let i = 1; i < initial.length; i += 1) {
            conns.push({ from: initial[i - 1].id, to: initial[i].id });
        }
        setConnections(conns);
    }, [open, messages]);

    const handleCardPointerDown = (e, card) => {
        if (e.target.closest('button')) return;
        if (e.altKey || e.button === 1) {
            e.preventDefault();
            panDragRef.current = {
                sx: e.clientX,
                sy: e.clientY,
                px: pan.x,
                py: pan.y,
            };
            setCanvasPanning(true);
            return;
        }
        if (e.button !== 0) return;
        setDragging(card.id);
        dragOffset.current = { x: e.clientX - card.x - pan.x, y: e.clientY - card.y - pan.y };
    };

    React.useEffect(() => {
        if (!dragging) return undefined;
        const handleMove = (e) => {
            setCards((prev) => prev.map((c) => (c.id === dragging
                ? {
                    ...c,
                    x: e.clientX - dragOffset.current.x - pan.x,
                    y: e.clientY - dragOffset.current.y - pan.y,
                }
                : c)));
        };
        const handleUp = () => setDragging(null);
        window.addEventListener('pointermove', handleMove);
        window.addEventListener('pointerup', handleUp);
        window.addEventListener('pointercancel', handleUp);
        return () => {
            window.removeEventListener('pointermove', handleMove);
            window.removeEventListener('pointerup', handleUp);
            window.removeEventListener('pointercancel', handleUp);
        };
    }, [dragging, pan]);

    React.useEffect(() => {
        if (!canvasPanning) return undefined;
        const handleMove = (e) => {
            const start = panDragRef.current;
            if (!start) return;
            setPan({
                x: start.px + (e.clientX - start.sx),
                y: start.py + (e.clientY - start.sy),
            });
        };
        const handleUp = () => {
            panDragRef.current = null;
            setCanvasPanning(false);
        };
        window.addEventListener('pointermove', handleMove);
        window.addEventListener('pointerup', handleUp);
        window.addEventListener('pointercancel', handleUp);
        return () => {
            window.removeEventListener('pointermove', handleMove);
            window.removeEventListener('pointerup', handleUp);
            window.removeEventListener('pointercancel', handleUp);
        };
    }, [canvasPanning]);

    const handleCanvasWheel = React.useCallback((e) => {
        if (e.target.closest('textarea')) return;
        e.preventDefault();
        const dx = e.shiftKey ? e.deltaY : (e.deltaX || 0);
        const dy = e.shiftKey ? 0 : e.deltaY;
        setPan((p) => ({ x: p.x - dx, y: p.y - dy }));
    }, []);

    React.useEffect(() => {
        const el = canvasRef.current;
        if (!el || !open) return undefined;
        el.addEventListener('wheel', handleCanvasWheel, { passive: false });
        return () => el.removeEventListener('wheel', handleCanvasWheel);
    }, [open, handleCanvasWheel]);

    const handleBackdropPointerDown = (e) => {
        if (e.target !== e.currentTarget) return;
        if (e.button !== 0) return;
        panDragRef.current = {
            sx: e.clientX,
            sy: e.clientY,
            px: pan.x,
            py: pan.y,
        };
        setCanvasPanning(true);
    };

    const addBlankCard = () => {
        setCards((prev) => [...prev, {
            id: `card-${Date.now()}`,
            role: 'note',
            content: '',
            x: 100 + Math.random() * 200,
            y: 100 + Math.random() * 200,
            width: 240,
        }]);
    };

    const updateCardContent = (id, content) => {
        setCards((prev) => prev.map((c) => (c.id === id ? { ...c, content } : c)));
    };

    const deleteCard = (id) => {
        setCards((prev) => prev.filter((c) => c.id !== id));
        setConnections((prev) => prev.filter((cn) => cn.from !== id && cn.to !== id));
    };

    const handleConnect = (cardId) => {
        if (!connecting) {
            setConnecting(cardId);
            return;
        }
        if (connecting !== cardId) {
            setConnections((prev) => [...prev, { from: connecting, to: cardId }]);
        }
        setConnecting(null);
    };

    const getCardCenter = (id) => {
        const card = cards.find((c) => c.id === id);
        if (!card) return { x: 0, y: 0 };
        return { x: card.x + card.width / 2, y: card.y + 50 };
    };

    if (!open) return null;

    const roleColor = (role) => {
        if (role === 'user') return { border: 'border-orange-500/20', bg: 'bg-orange-500/[0.03]', label: 'text-orange-400' };
        if (role === 'assistant') return { border: 'border-violet-500/20', bg: 'bg-violet-500/[0.03]', label: 'text-violet-400' };
        if (role === 'kernel') return { border: 'border-cyan-500/20', bg: 'bg-cyan-500/[0.03]', label: 'text-cyan-400' };
        return { border: 'border-slate-500/20', bg: 'bg-slate-500/[0.03]', label: 'text-slate-400' };
    };

    return (
        <div
            ref={panelRef}
            data-testid="canvas-mode"
            role="dialog"
            aria-modal="true"
            aria-labelledby="canvas-mode-title"
            className="fixed inset-0 z-50 bg-shell-canvas flex flex-col"
        >
            <div className="flex items-center justify-between px-4 py-2 border-b border-white/[0.04] bg-shell-surface/80 z-10">
                <div className="flex items-center gap-3">
                    <h2 id="canvas-mode-title" className="text-[13px] font-medium text-slate-200">Canvas</h2>
                    <span className="text-[10px] text-slate-500 font-mono">{cards.length} cards</span>
                    <span className="text-[9px] text-slate-600 font-mono hidden sm:inline max-w-[280px] truncate" title="Pan the board">
                        Wheel pan · empty space drag · Alt or middle-drag on cards
                    </span>
                </div>
                <div className="flex items-center gap-2">
                    <button type="button" onClick={addBlankCard} className="px-2.5 py-1 rounded-lg bg-violet-500/15 text-violet-300 text-[10px] font-medium hover:bg-violet-500/25 transition-all">+ Card</button>
                    {connecting && <span className="text-[10px] text-cyan-400 animate-pulse">Click another card to connect…</span>}
                    <button type="button" data-testid="canvas-mode-close" data-accessible-overlay-close onClick={onClose} title="Close Canvas Mode" aria-label="Close Canvas Mode" className="text-slate-500 hover:text-slate-300 text-[12px]"><span aria-hidden="true">✕</span></button>
                </div>
            </div>

            <div ref={canvasRef} className="flex-1 relative overflow-hidden">
                <div
                    role="presentation"
                    onPointerDown={handleBackdropPointerDown}
                    style={{ transform: `translate(${pan.x}px, ${pan.y}px)` }}
                    className={`absolute inset-0 z-0 ${canvasPanning ? 'cursor-grabbing' : 'cursor-grab'}`}
                />
                <svg className="absolute inset-0 w-full h-full pointer-events-none z-[1]" style={{ transform: `translate(${pan.x}px, ${pan.y}px)` }}>
                    {connections.map((conn, i) => {
                        const from = getCardCenter(conn.from);
                        const to = getCardCenter(conn.to);
                        return (
                            <line key={i} x1={from.x} y1={from.y} x2={to.x} y2={to.y} stroke="rgba(139,92,246,0.15)" strokeWidth="1.5" strokeDasharray="4 4" />
                        );
                    })}
                </svg>

                <div style={{ transform: `translate(${pan.x}px, ${pan.y}px)` }} className="absolute inset-0 z-[2] pointer-events-none">
                    {cards.map((card) => {
                        const c = roleColor(card.role);
                        return (
                            <div
                                key={card.id}
                                className={`absolute rounded-xl border ${c.border} ${c.bg} backdrop-blur-sm shadow-lg transition-shadow pointer-events-auto ${dragging === card.id ? 'shadow-xl z-10' : ''} ${connecting === card.id ? 'ring-2 ring-cyan-400/40' : ''}`}
                                style={{ left: card.x, top: card.y, width: card.width }}
                                onPointerDown={(e) => handleCardPointerDown(e, card)}
                            >
                                <div className="flex items-center justify-between px-2.5 py-1.5 border-b border-white/[0.04]">
                                    <span className={`text-[9px] font-mono uppercase ${c.label}`}>{card.role}</span>
                                    <div className="flex items-center gap-1">
                                        <button type="button" onClick={() => handleConnect(card.id)} className="text-[9px] text-cyan-500 hover:text-cyan-300 transition-colors" title="Connect">⟶</button>
                                        <button type="button" onClick={() => deleteCard(card.id)} title="Delete card" aria-label="Delete card" className="text-[9px] text-slate-600 hover:text-red-400 transition-colors"><span aria-hidden="true">✕</span></button>
                                    </div>
                                </div>
                                {card.role === 'note' ? (
                                    <textarea
                                        value={card.content}
                                        onChange={(e) => updateCardContent(card.id, e.target.value)}
                                        placeholder="Type a note…"
                                        className="w-full bg-transparent px-2.5 py-2 text-[11px] text-slate-300 outline-none resize-none min-h-16 max-h-32"
                                    />
                                ) : (
                                    <div className="px-2.5 py-2 text-[11px] text-slate-300 leading-relaxed max-h-32 overflow-y-auto whitespace-pre-wrap">
                                        {card.content}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
});
export default CanvasMode;

import React from 'react';
import { useModalAccessibility } from '../hooks/useModalAccessibility.js';

const STORAGE_PREFIX = 'neuralshell_canvas_layout_v1_';
const SCALE_MIN = 0.35;
const SCALE_MAX = 2.75;
const SAVE_DEBOUNCE_MS = 400;

function storageKey(sessionKey) {
    const safe = String(sessionKey || 'default').replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 120);
    return `${STORAGE_PREFIX}${safe}`;
}

function validateSnapshot(raw) {
    if (!raw || typeof raw !== 'object') return null;
    if (Number(raw.version) !== 1) return null;
    if (!Array.isArray(raw.cards)) return null;
    if (!Array.isArray(raw.connections)) return null;
    const pan = raw.pan && typeof raw.pan === 'object' ? raw.pan : {};
    const px = Number(pan.x);
    const py = Number(pan.y);
    if (!Number.isFinite(px) || !Number.isFinite(py)) return null;
    const sc = Number(raw.scale);
    const scale = Number.isFinite(sc) && sc > 0 ? Math.min(SCALE_MAX, Math.max(SCALE_MIN, sc)) : 1;
    return {
        version: 1,
        cards: raw.cards,
        connections: raw.connections,
        pan: { x: px, y: py },
        scale,
    };
}

function loadSnapshot(sessionKey) {
    if (typeof window === 'undefined' || !window.localStorage) return null;
    try {
        const raw = JSON.parse(window.localStorage.getItem(storageKey(sessionKey)) || 'null');
        return validateSnapshot(raw);
    } catch {
        return null;
    }
}

function saveSnapshot(sessionKey, payload) {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try {
        const body = JSON.stringify({ version: 1, ...payload });
        if (body.length > 1_500_000) return;
        window.localStorage.setItem(storageKey(sessionKey), body);
    } catch {
        /* quota or private mode */
    }
}

function buildChatCardsFromMessages(messages) {
    const filtered = messages.filter((m) => m && !m._streaming);
    const chatCards = filtered.map((msg, i) => ({
        id: `card-${i}`,
        role: msg.role,
        content: String(msg.content || '').slice(0, 300),
        x: 80 + (i % 4) * 280,
        y: 60 + Math.floor(i / 4) * 200,
        width: 240,
    }));
    const conns = [];
    for (let i = 1; i < chatCards.length; i += 1) {
        conns.push({ from: chatCards[i - 1].id, to: chatCards[i].id });
    }
    return { chatCards, conns };
}

const CanvasMode = React.memo(function CanvasMode({ open, onClose, chatLog, sessionKey = 'default' }) {
    const messages = Array.isArray(chatLog) ? chatLog : [];
    const [cards, setCards] = React.useState([]);
    const [dragging, setDragging] = React.useState(null);
    const [pan, setPan] = React.useState({ x: 0, y: 0 });
    const [scale, setScale] = React.useState(1);
    const [connecting, setConnecting] = React.useState(null);
    const [connections, setConnections] = React.useState([]);
    const [canvasPanning, setCanvasPanning] = React.useState(false);
    const dragOffset = React.useRef({ sx: 0, sy: 0, ox: 0, oy: 0 });
    const panDragRef = React.useRef(null);
    const scaleRef = React.useRef(1);
    const pinchRef = React.useRef(null);
