            setDragging(null);
            setConnecting(null);
            setCanvasPanning(false);
            panDragRef.current = null;
            pinchRef.current = null;
            return;
        }
        const snap = loadSnapshot(sessionKey);
        if (snap) {
            setCards(snap.cards);
            setConnections(snap.connections);
            setPan(snap.pan);
            setScale(snap.scale);
        } else {
            const { chatCards, conns } = buildChatCardsFromMessages(messages);
            setCards(chatCards);
            setConnections(conns);
            setPan({ x: 0, y: 0 });
            setScale(1);
        }
    }, [open, sessionKey]);

    React.useEffect(() => {
        if (open) scheduleSave();
    }, [open, cards, connections, pan, scale, scheduleSave]);

    const resyncFromChat = React.useCallback(() => {
        const notes = cards.filter((c) => c.role === 'note');
        const { chatCards, conns } = buildChatCardsFromMessages(messages);
        const noteIdSet = new Set(notes.map((n) => n.id));
        const kept = connections.filter((cn) => noteIdSet.has(cn.from) && noteIdSet.has(cn.to));
        setCards([...chatCards, ...notes]);
        setConnections([...conns, ...kept]);
        setPan({ x: 0, y: 0 });
        setScale(1);
        scheduleSave();
    }, [cards, connections, messages, scheduleSave]);

    const handleCardPointerDown = (e, card) => {
        if (e.target.closest('button')) return;
        if (e.altKey || e.button === 1) {
            e.preventDefault();
            panDragRef.current = {
                sx: e.clientX,
                sy: e.clientY,
                px: pan.x,
                py: pan.y,
            };
            setCanvasPanning(true);
            return;
        }
        if (e.button !== 0) return;
        setDragging(card.id);
        const sc = scaleRef.current || 1;
        dragOffset.current = {
            sx: e.clientX,
            sy: e.clientY,
            ox: card.x,
            oy: card.y,
            sc,
        };
    };

    React.useEffect(() => {
        if (!dragging) return undefined;
        const handleMove = (e) => {
            const d = dragOffset.current;
            const sc = d.sc || 1;
            setCards((prev) => prev.map((c) => (c.id === dragging
                ? {
                    ...c,
                    x: d.ox + (e.clientX - d.sx) / sc,
                    y: d.oy + (e.clientY - d.sy) / sc,
                }
                : c)));
        };
        const handleUp = () => setDragging(null);
        window.addEventListener('pointermove', handleMove);
        window.addEventListener('pointerup', handleUp);
        window.addEventListener('pointercancel', handleUp);
        return () => {
            window.removeEventListener('pointermove', handleMove);
            window.removeEventListener('pointerup', handleUp);
            window.removeEventListener('pointercancel', handleUp);
        };
    }, [dragging]);

    React.useEffect(() => {
        if (!canvasPanning) return undefined;
        const handleMove = (e) => {
            const start = panDragRef.current;
            if (!start) return;
            setPan({
                x: start.px + (e.clientX - start.sx),
                y: start.py + (e.clientY - start.sy),
            });
        };
        const handleUp = () => {
            panDragRef.current = null;
            setCanvasPanning(false);
        };
        window.addEventListener('pointermove', handleMove);
        window.addEventListener('pointerup', handleUp);
        window.addEventListener('pointercancel', handleUp);
        return () => {
            window.removeEventListener('pointermove', handleMove);
            window.removeEventListener('pointerup', handleUp);
            window.removeEventListener('pointercancel', handleUp);
        };
    }, [canvasPanning]);

    const handleCanvasWheel = React.useCallback((e) => {
        if (e.target.closest('textarea')) return;
        e.preventDefault();
        if (e.ctrlKey || e.metaKey) {
            const delta = e.deltaY;
            const factor = delta > 0 ? 0.94 : 1.06;
            setScale((s) => Math.min(SCALE_MAX, Math.max(SCALE_MIN, s * factor)));
            return;
        }
        const dx = e.shiftKey ? e.deltaY : (e.deltaX || 0);
        const dy = e.shiftKey ? 0 : e.deltaY;
        setPan((p) => ({ x: p.x - dx, y: p.y - dy }));
    }, []);

    React.useEffect(() => {
        const el = canvasRef.current;
        if (!el || !open) return undefined;
        el.addEventListener('wheel', handleCanvasWheel, { passive: false });
        return () => el.removeEventListener('wheel', handleCanvasWheel);
    }, [open, handleCanvasWheel]);

    React.useEffect(() => {
        const el = canvasRef.current;
        if (!el || !open) return undefined;
        const dist = (t0, t1) => {
            const dx = t0.clientX - t1.clientX;
            const dy = t0.clientY - t1.clientY;
            return Math.hypot(dx, dy) || 1;
        };
        const onTouchStart = (e) => {
            if (e.touches.length === 2) {
                pinchRef.current = {
                    d0: dist(e.touches[0], e.touches[1]),
                    s0: scaleRef.current,
                };
            }
        };
        const onTouchMove = (e) => {
            if (e.touches.length !== 2 || !pinchRef.current) return;
            e.preventDefault();
