    const roleColor = (role) => {
        if (role === 'user') return { border: 'border-orange-500/20', bg: 'bg-orange-500/[0.03]', label: 'text-orange-400' };
        if (role === 'assistant') return { border: 'border-violet-500/20', bg: 'bg-violet-500/[0.03]', label: 'text-violet-400' };
        if (role === 'kernel') return { border: 'border-cyan-500/20', bg: 'bg-cyan-500/[0.03]', label: 'text-cyan-400' };
        return { border: 'border-slate-500/20', bg: 'bg-slate-500/[0.03]', label: 'text-slate-400' };
    };

    return (
        <div
            ref={panelRef}
            data-testid="canvas-mode"
            role="dialog"
            aria-modal="true"
            aria-labelledby="canvas-mode-title"
            className="fixed inset-0 z-50 bg-shell-canvas flex flex-col"
        >
            <div className="flex items-center justify-between px-4 py-2 border-b border-white/[0.04] bg-shell-surface/80 z-10 gap-2 flex-wrap">
                <div className="flex items-center gap-3 min-w-0">
                    <h2 id="canvas-mode-title" className="text-[13px] font-medium text-slate-200 shrink-0">Canvas</h2>
                    <span className="text-[10px] text-slate-500 font-mono shrink-0">{cards.length} cards</span>
                    <span className="text-[10px] text-slate-500 font-mono shrink-0">{Math.round(scale * 100)}%</span>
                    <span className="text-[9px] text-slate-600 font-mono hidden md:inline truncate" title="Navigation">
                        Wheel pan · Ctrl wheel zoom · pinch · Alt / middle-drag
                    </span>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                    <button
                        type="button"
                        data-testid="canvas-mode-resync"
                        onClick={resyncFromChat}
                        className="px-2.5 py-1 rounded-lg border border-white/10 bg-white/[0.04] text-slate-200 text-[10px] font-medium hover:bg-white/[0.08] transition-all"
                        title="Rebuild cards from the current transcript. Keeps sticky notes and links between notes."
                    >
                        Resync chat
                    </button>
                    <button type="button" onClick={addBlankCard} className="px-2.5 py-1 rounded-lg bg-violet-500/15 text-violet-300 text-[10px] font-medium hover:bg-violet-500/25 transition-all">+ Card</button>
                    {connecting && <span className="text-[10px] text-cyan-400 animate-pulse">Click another card…</span>}
