                </div>
            </div>

            <div ref={canvasRef} className="flex-1 relative overflow-hidden">
                <div
                    role="presentation"
                    onPointerDown={handleBackdropPointerDown}
                    style={{ transform: worldTransform, transformOrigin: '0 0' }}
                    className={`absolute inset-0 z-0 ${canvasPanning ? 'cursor-grabbing' : 'cursor-grab'}`}
                />
                <svg className="absolute inset-0 w-full h-full pointer-events-none z-[1]" style={{ transform: worldTransform, transformOrigin: '0 0' }}>
