                        const from = getCardCenter(conn.from);
                        const to = getCardCenter(conn.to);
                        return (
                            <line key={i} x1={from.x} y1={from.y} x2={to.x} y2={to.y} stroke="rgba(139,92,246,0.15)" strokeWidth="1.5" strokeDasharray="4 4" />
                        );
                    })}
                </svg>

                <div style={{ transform: worldTransform, transformOrigin: '0 0' }} className="absolute inset-0 z-[2] pointer-events-none">
                    {cards.map((card) => {
                        const c = roleColor(card.role);
                        return (
                            <div
                                key={card.id}
                                className={`absolute rounded-xl border ${c.border} ${c.bg} backdrop-blur-sm shadow-lg transition-shadow pointer-events-auto ${dragging === card.id ? 'shadow-xl z-10' : ''} ${connecting === card.id ? 'ring-2 ring-cyan-400/40' : ''}`}
