                                onPointerDown={(e) => handleCardPointerDown(e, card)}
                            >
                                <div className="flex items-center justify-between px-2.5 py-1.5 border-b border-white/[0.04]">
                                    <span className={`text-[9px] font-mono uppercase ${c.label}`}>{card.role}</span>
                                    <div className="flex items-center gap-1">
                                        <button type="button" onClick={() => handleConnect(card.id)} className="text-[9px] text-cyan-500 hover:text-cyan-300 transition-colors" title="Connect">⟶</button>
