+  async function resolveLiveWindow(appHandle, candidate, timeoutMs = 10000) {
+    const started = Date.now();
+    let current = candidate;
+    while (Date.now() - started < timeoutMs) {
+      if (current && !current.isClosed()) return current;
+      const liveWindows = appHandle.windows().filter((win) => !win.isClosed());
+      if (liveWindows.length > 0) return liveWindows[liveWindows.length - 1];
+      await new Promise((resolve) => setTimeout(resolve, 250));
