+  async function waitForMainWindow(appHandle, timeoutMs = MAX_PER_ATTEMPT_TIMEOUT_MS) {
+    const proc = appHandle.process();
+    const output = captureProcessOutput(proc);
+    let settled = false;
+    const failWithOutput = (message) => {
+      const suffix = output.getOutput();
+      return new Error(suffix ? `${message}\n${suffix}` : message);
+    };
+    const cleanup = () => {
+      settled = true;
+      output.dispose();
+    };
+    const exitPromise = new Promise((_, reject) => {
+      const onExit = (code, signal) => {
+        if (settled) return;
+        reject(failWithOutput(`Electron exited before first window (code=${code}, signal=${signal || "none"})`));
+      };
+      const onError = (err) => {
+        if (settled) return;
+        reject(failWithOutput(`Electron process error before first window: ${err && err.message ? err.message : String(err)}`));
+      };
+      proc.once("exit", onExit);
+      proc.once("error", onError);
+    });
