+      const attemptsLeft = attempts - i;
+      const perAttemptTimeout = Math.max(
+        30000,
+        Math.min(
+          MAX_PER_ATTEMPT_TIMEOUT_MS,
+          Math.floor((remainingMs - CLOSE_TIMEOUT_MS) / Math.max(1, attemptsLeft)),
